  var RuntimeDerivedIndexByWorld = new Map();

  function runtimeWorldKey(world){
    return String((world && world.meta && world.meta.id) || 'anonymous-world');
  }

  function createRuntimeDerivedIndex(world){
    return {
      world: world || null,
      stamp: '',
      matchStamp: '',
      fixtureStamp: '',
      slotStamp: '',
      matchById: {},
      matchByFixtureId: {},
      matchesBySeason: {},
      matchesBySeasonCompetition: {},
      matchesByTieId: {},
      fixtureById: {},
      fixturesBySlot: {},
      slotIndexByKey: {}
    };
  }

  function runtimeArrayVersion(list){
    return list && list.length ? String(list.length) + ':' + String((list[list.length - 1] || {}).id || '') : '0';
  }

  function runtimeIndexStamp(world){
    var matches = ((((world || {}).history || {}).matches) || []);
    var fixtures = ((((world || {}).calendar || {}).fixtures) || []);
    var slots = ((((world || {}).calendar || {}).slots) || []);
    return [
      Number((((world || {}).meta || {}).seasonNumber) || 1),
      runtimeArrayVersion(matches),
      runtimeArrayVersion(fixtures),
      runtimeArrayVersion(slots)
    ].join('|');
  }

  function runtimeMatchStamp(world){
    return [Number((((world || {}).meta || {}).seasonNumber) || 1), runtimeArrayVersion(((((world || {}).history || {}).matches) || []))].join('|');
  }

  function runtimeFixtureStamp(world){
    return [Number((((world || {}).meta || {}).seasonNumber) || 1), runtimeArrayVersion(((((world || {}).calendar || {}).fixtures) || []))].join('|');
  }

  function runtimeSlotStamp(world){
    return [Number((((world || {}).meta || {}).seasonNumber) || 1), runtimeArrayVersion(((((world || {}).calendar || {}).slots) || []))].join('|');
  }

  function resetRuntimeDerivedIndex(world){
    var key = runtimeWorldKey(world);
    var idx = createRuntimeDerivedIndex(world);
    RuntimeDerivedIndexByWorld.set(key, idx);
    return idx;
  }

  function ensureRuntimeDerivedIndex(world, mode){
    if (!world) return createRuntimeDerivedIndex(null);
    var key = runtimeWorldKey(world);
    var idx = RuntimeDerivedIndexByWorld.get(key);
    if (!idx || idx.world !== world) idx = resetRuntimeDerivedIndex(world);
    var wantsSlots = mode !== 'matches' && mode !== 'fixtures';
    var wantsFixtures = mode !== 'matches' && mode !== 'slots';
    var wantsMatches = mode !== 'fixtures' && mode !== 'slots';
    if (wantsSlots) {
      var slotStamp = runtimeSlotStamp(world);
      if (idx.slotStamp !== slotStamp) {
        idx.slotStamp = slotStamp;
        idx.slotIndexByKey = {};
        ((((world || {}).calendar || {}).slots) || []).forEach(function(slot, index){ if (slot && slot.key) idx.slotIndexByKey[slot.key] = index; });
      }
    }
    if (wantsFixtures) {
      var fixtureStamp = runtimeFixtureStamp(world);
      if (idx.fixtureStamp !== fixtureStamp) {
        idx.fixtureStamp = fixtureStamp;
        idx.fixtureById = {};
        idx.fixturesBySlot = {};
        ((((world || {}).calendar || {}).fixtures) || []).forEach(function(fixture){
          if (!fixture) return;
          if (fixture.id) idx.fixtureById[fixture.id] = fixture;
          var slotKey = String(fixture.slotKey || '');
          if (!idx.fixturesBySlot[slotKey]) idx.fixturesBySlot[slotKey] = [];
          idx.fixturesBySlot[slotKey].push(fixture);
        });
      }
    }
    if (wantsMatches) {
      var matchStamp = runtimeMatchStamp(world);
      if (idx.matchStamp !== matchStamp) {
        idx.matchStamp = matchStamp;
        idx.matchById = {};
        idx.matchByFixtureId = {};
        idx.matchesBySeason = {};
        idx.matchesBySeasonCompetition = {};
        idx.matchesByTieId = {};
        ((((world || {}).history || {}).matches) || []).forEach(function(match){
          if (!match) return;
          if (match.id) idx.matchById[match.id] = match;
          if (match.fixtureId) idx.matchByFixtureId[match.fixtureId] = match;
          var season = String(Number(match.season || 1));
          if (!idx.matchesBySeason[season]) idx.matchesBySeason[season] = [];
          idx.matchesBySeason[season].push(match);
          var compKey = season + '|' + String(match.competition || '');
          if (!idx.matchesBySeasonCompetition[compKey]) idx.matchesBySeasonCompetition[compKey] = [];
          idx.matchesBySeasonCompetition[compKey].push(match);
          if (match.tieId) {
            var tieKey = String(match.tieId);
            if (!idx.matchesByTieId[tieKey]) idx.matchesByTieId[tieKey] = [];
            idx.matchesByTieId[tieKey].push(match);
          }
        });
      }
    }
    idx.stamp = runtimeIndexStamp(world);
    return idx;
  }

  function invalidateRuntimeDerivedIndex(world){
    if (world) RuntimeDerivedIndexByWorld.delete(runtimeWorldKey(world));
    else if (AppState && AppState.world) RuntimeDerivedIndexByWorld.delete(runtimeWorldKey(AppState.world));
    else RuntimeDerivedIndexByWorld.clear();
    if (AppState && AppState.ui) AppState.ui.statisticsDerivedCache = null;
  }

  function indexedMatchesForSeason(world, seasonNumber){
    var idx = ensureRuntimeDerivedIndex(world, 'matches');
    return (idx.matchesBySeason[String(Number(seasonNumber || 1))] || []);
  }

  function indexedMatchesForSeasonCompetition(world, seasonNumber, competition){
    var idx = ensureRuntimeDerivedIndex(world, 'matches');
    return (idx.matchesBySeasonCompetition[String(Number(seasonNumber || 1)) + '|' + String(competition || '')] || []);
  }

  function indexedFixturesForSlot(world, slotKey){
    var idx = ensureRuntimeDerivedIndex(world, 'fixtures');
    return (idx.fixturesBySlot[String(slotKey || '')] || []);
  }

