    StaticData.matchSummaryBlocks.summary = pushUnique(StaticData.matchSummaryBlocks.summary, [{"id": "summary_close_win_v161_001", "tags": ["win", "close_match"], "template": "{winner} setzt sich in einem engen Spiel durch, weil die entscheidenden Szenen etwas sauberer ausgespielt werden."}, {"id": "summary_deserved_win_v161_001", "tags": ["win", "dominance"], "template": "{winner} hat mehr Zugriff auf die gefährlichen Zonen und gewinnt deshalb nachvollziehbar."}, {"id": "summary_efficient_win_v161_001", "tags": ["win", "efficiency"], "template": "{winner} braucht nicht viele klare Chancen, nutzt die vorhandenen Momente aber konsequenter."}, {"id": "summary_draw_xg_v161_001", "tags": ["draw"], "template": "Beide Teams finden Phasen mit Kontrolle, im letzten Drittel fehlt jedoch die letzte Klarheit."}, {"id": "summary_scoreless_v161_001", "tags": ["draw", "low_event"], "template": "Die Partie bleibt taktisch eng, weil beide Defensivreihen viele Aktionen früh entschärfen."}, {"id": "summary_wasteful_v161_001", "tags": ["high_xg_no_win"], "template": "{team} kommt zu genügend Ansätzen, lässt aber in den entscheidenden Momenten Präzision vermissen."}, {"id": "summary_wing_v161_001", "tags": ["wing_focus"], "template": "Die Außenbahnen geben dem Spiel Struktur, doch nicht jede breite Aktion führt zu klarer Gefahr."}, {"id": "summary_counter_v161_001", "tags": ["counter"], "template": "Umschaltmomente verändern mehrfach das Tempo und zwingen beide Teams zu schnellen Reaktionen."}, {"id": "summary_keeper_v161_001", "tags": ["keeper"], "template": "Der Torwart verhindert in wichtigen Momenten, dass das Spiel deutlicher kippt."}, {"id": "summary_red_v161_001", "tags": ["red_card"], "template": "Der Platzverweis verändert Rhythmus und Raumaufteilung sichtbar."}, {"id": "summary_pressing_v161_001", "tags": ["pressing_win"], "template": "Hoher Druck auf den Ball erzeugt Ballgewinne, aber auch intensive Laufwege."}, {"id": "summary_pressing_bypassed_v161_001", "tags": ["pressing_bypassed"], "template": "Das hohe Anlaufen bringt Risiko, weil der Gegner mehrfach hinter die erste Linie kommt."}, {"id": "summary_late_v161_001", "tags": ["late_goal", "close_match"], "template": "Die Schlussphase verändert die Bewertung eines lange offenen Spiels."}, {"id": "summary_fatigue_v161_001", "tags": ["fatigue"], "template": "Mit zunehmender Spielzeit werden die Abstände größer und einzelne Fehler wahrscheinlicher."}, {"id": "summary_default_v161_001", "tags": ["default"], "template": "Das Spiel entwickelt sich über mehrere Phasen, in denen beide Teams unterschiedliche Lösungen finden."}]);
    StaticData.matchShortReportBlocks = pushUnique(StaticData.matchShortReportBlocks || [], [{"id": "short_scoreless_tactical_001", "tags": ["draw", "low_event"], "headline": "Taktisch enges Remis", "template": "Das Spiel blieb lange von Ordnung und Absicherung geprägt. {teamLabel} fand zwar einzelne Räume, doch {opponentLabel} verteidigte die gefährlichen Zonen konsequent. Ohne klare letzte Aktion blieb das Remis folgerichtig."}, {"id": "short_scoreless_chances_001", "tags": ["draw", "high_xg_no_win", "scoreless"], "headline": "Chancen ohne Treffer", "template": "Beide Teams kamen zu Phasen mit Gefahr, ließen aber im Abschluss die nötige Genauigkeit vermissen. {teamLabel} hatte etwas mehr von den guten Momenten, konnte daraus aber keinen Treffer erzwingen. So blieb ein Spiel ohne Tor, aber nicht ohne Ansätze."}, {"id": "short_close_win_control_001", "tags": ["win", "close_match"], "headline": "Knapper Sieg mit Kontrolle", "template": "{winnerLabel} gewann kein einseitiges Spiel, wirkte in den entscheidenden Räumen aber etwas stabiler. {loserLabel} blieb lange im Spiel, fand jedoch zu selten die ganz klare Antwort. Am Ende reichte die bessere Kontrolle in wenigen Schlüsselszenen."}, {"id": "short_close_win_effort_001", "tags": ["win", "close_match"], "headline": "Umkämpfter Erfolg", "template": "Die Partie verlangte {winnerLabel} viel Geduld ab. {loserLabel} verteidigte kompakt und setzte eigene Akzente, doch der entscheidende Moment fiel auf die andere Seite. Der Sieg ist knapp, aber aus dem Verlauf erklärbar."}, {"id": "short_wasteful_draw_001", "tags": ["draw", "high_xg_no_win"], "headline": "Mehr Chancen, kein Lohn", "template": "{teamLabel} erspielte sich die besseren Möglichkeiten, fand aber nicht oft genug den sauberen Abschluss. {opponentLabel} verteidigte mit Einsatz und überstand mehrere Druckphasen. Das Ergebnis fühlt sich für {teamLabel} deshalb eher wie zwei verlorene Punkte an."}, {"id": "short_keeper_point_001", "tags": ["keeper", "draw"], "headline": "Torwart hält das Spiel offen", "template": "Der Torwart wurde in mehreren Szenen zum entscheidenden Faktor. {teamLabel} brachte gute Abschlüsse zustande, doch {opponentLabel} blieb durch starke Paraden im Spiel. Dadurch bekam die Partie ein deutlich engeres Ergebnisbild."}, {"id": "short_wing_right_001", "tags": ["right_side", "wing_focus"], "headline": "Rechte Seite prägt das Spiel", "template": "{teamLabel} suchte häufig den Weg über rechts und brachte dort Tempo in die Partie. {opponentLabel} musste immer wieder verschieben, konnte die entscheidenden Zuspiele aber nicht immer verhindern. Die Wirkung dieser Seite prägte den Spielverlauf sichtbar."}, {"id": "short_wing_left_001", "tags": ["left_side", "wing_focus"], "headline": "Linke Seite als Ausgangspunkt", "template": "{teamLabel} fand über links wiederholt Raum und zwang {opponentLabel} zu langen Wegen. Nicht jede Aktion wurde gefährlich, aber die Richtung des Spiels war klar erkennbar. Die linke Seite wurde zum wiederkehrenden Muster."}, {"id": "short_counter_risk_001", "tags": ["counter"], "headline": "Räume nach Ballverlusten", "template": "Umschaltmomente gaben dem Spiel immer wieder Tempo. {teamLabel} nutzte offene Räume nach Ballgewinnen, während {opponentLabel} nicht jede Szene sauber absicherte. Dadurch entstanden Chancen, die aus der Grundordnung allein nicht erklärbar gewesen wären."}, {"id": "short_pressing_cost_001", "tags": ["pressing", "fatigue"], "headline": "Pressing mit Preis", "template": "{teamLabel} erzeugte mit hohem Anlaufen mehrere Ballgewinne, musste dafür aber auch große Wege gehen. Mit zunehmender Dauer wurden die Abstände größer und {opponentLabel} fand mehr Lösungen. Das Pressing war wirksam, aber nicht ohne Risiko."}, {"id": "short_lead_protected_001", "tags": ["win", "late_extension"], "headline": "Führung gut verwaltet", "template": "Nach dem Vorsprung spielte {winnerLabel} kontrollierter und nahm etwas Risiko aus den eigenen Aktionen. {loserLabel} hatte mehr Ballbesitzphasen, kam aber nicht regelmäßig zu klaren Chancen. Die Verwaltung der Führung wirkte deshalb nachvollziehbar."}, {"id": "short_trailing_pressure_001", "tags": ["late_goal", "close_match"], "headline": "Später Druck verändert das Spiel", "template": "In der Schlussphase erhöhte {teamLabel} das Risiko und brachte mehr Spieler in gefährliche Räume. {opponentLabel} verteidigte tiefer, musste aber mehrere brenzlige Szenen überstehen. Der späte Verlauf passte zur veränderten Ausrichtung."}, {"id": "short_clear_efficiency_001", "tags": ["win", "clear_win", "efficiency"], "headline": "Klare Effizienz", "template": "{winnerLabel} nutzte die entscheidenden Chancen mit hoher Konsequenz. {loserLabel} fand zwar eigene Ansätze, bekam aber die wichtigsten Szenen nicht verteidigt. Das Ergebnis wirkt dadurch deutlich, ohne dass jeder Spielabschnitt einseitig war."}, {"id": "short_dominant_no_gloss_001", "tags": ["win", "dominance"], "headline": "Verdient ohne Glanz", "template": "{winnerLabel} hatte mehr Kontrolle und kam häufiger in die relevanten Zonen. Nicht alles wirkte spielerisch sauber, aber die bessere Struktur führte zu den klareren Momenten. {loserLabel} blieb vor allem über einzelne Phasen gefährlich."}, {"id": "short_default_v161_001", "tags": ["default"], "headline": "Spiel mit wechselnden Phasen", "template": "Keine Mannschaft bestimmte die Partie durchgehend. {teamLabel} fand zeitweise gute Lösungen, {opponentLabel} reagierte in anderen Phasen stabiler. Entscheidend waren die Situationen, in denen aus Kontrolle auch echte Gefahr wurde."}]);
