  function uid(prefix){
    return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2,8);
  }

  function fixtureIdPart(value){
    return String(value == null || value === '' ? 'x' : value).toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/[^a-z0-9]+/g,'').slice(0,24) || 'x';
  }

  function fixtureIdPad(value, width){
    var num = Math.max(0, Number(value || 0));
    var out = String(Math.floor(num));
    while (out.length < (width || 2)) out = '0' + out;
    return out;
  }

  function fixtureStableCompetitionCode(fixture){
    if (!fixture) return 'fx';
    if (fixture.competition === 'cup' || fixture.competition === 'national-cup') return 'ncup';
    if (fixture.competition === 'fiebercup' && fixture.stage === 'qualification') return 'fbcq';
    if (fixture.competition === 'fiebercup') return 'fbc';
    if (fixture.competition === 'league' && fixture.roundType === 'relegation') return 'rel';
    if (fixture.competition === 'league') return 'league';
    return fixtureIdPart(fixture.competition || 'fixture');
  }

  function fixtureStableContext(fixture){
    if (!fixture) return 'global';
    if (fixture.competition === 'league') return fixtureIdPart(fixture.leagueKey || fixture.countryName || 'league');
    if (fixture.competition === 'cup' || fixture.competition === 'national-cup') return fixtureIdPart(fixture.countryName || 'cup');
    if (fixture.competition === 'fiebercup' && fixture.stage === 'qualification') return fixtureIdPart(fixture.countryName || 'q');
    if (fixture.competition === 'fiebercup' && fixture.stage === 'group') return 'g' + fixtureIdPart(fixture.groupId || fixture.groupLabel || 'group');
    if (fixture.competition === 'fiebercup') return 'ko';
    return fixtureIdPart(fixture.leagueKey || fixture.countryName || fixture.competitionLabel || 'global');
  }

  function fixtureStableRound(fixture){
    if (!fixture) return 'r00';
    var round = '';
    if (fixture.competition === 'league' && fixture.roundType === 'league') round = 'md' + fixtureIdPad(fixture.matchday || fixture.roundNumber || 0, 2);
    else if (fixture.competition === 'league' && fixture.roundType === 'relegation') round = 'rel' + fixtureIdPad(fixture.leg || fixture.roundNumber || 0, 1);
    else if (fixture.competition === 'cup' || fixture.competition === 'national-cup') round = 'r' + fixtureIdPad(fixture.roundNumber || fixture.matchday || 0, 1);
    else if (fixture.competition === 'fiebercup' && fixture.stage === 'qualification') round = fixture.roundType === 'qualification_final' ? 'final' : 'semi';
    else if (fixture.competition === 'fiebercup' && fixture.stage === 'group') round = 'md' + fixtureIdPad(fixture.matchday || fixture.roundNumber || 0, 2);
    else if (fixture.competition === 'fiebercup') {
      var map = { round_of_16:'af', quarterfinal:'vf', semifinal:'hf', final:'final' };
      round = map[fixture.roundType] || fixtureIdPart(fixture.roundType || 'ko');
      if (fixture.leg) round += 'l' + fixtureIdPad(fixture.leg, 1);
    }
    else round = fixtureIdPart(fixture.roundType || fixture.roundNumber || fixture.matchday || 'r');
    return round || 'r00';
  }

  function stableFixtureId(world, fixture, fallbackIndex){
    fixture = fixture || {};
    var season = fixtureIdPad(fixture.season || (((world||{}).meta||{}).seasonNumber) || 1, 3);
    var idx = fixtureIdPad(Number(fixture.pairIndex != null ? fixture.pairIndex : fallbackIndex || 0) + 1, 5);
    return ['fx', fixtureStableCompetitionCode(fixture), fixtureStableContext(fixture), season, fixtureStableRound(fixture), idx].join(':');
  }

  function fixtureHasMatchLink(world, fixture){
    if (!world || !fixture || !fixture.id) return false;
    var direct = fixture.playedMatchId ? matchById(world, fixture.playedMatchId) : null;
    if (direct && direct.fixtureId === fixture.id) return true;
    return playedMatches(world).some(function(match){ return match && match.fixtureId === fixture.id; });
  }

  function assignStableFixtureIds(world, fixtures){
    var list = fixtures || ((((world||{}).calendar||{}).fixtures)||[]);
    var used = {};
    ((((world||{}).calendar||{}).fixtures)||[]).forEach(function(fixture){
      if (!fixture || !fixture.id) return;
      if (String(fixture.id).indexOf('fx:') === 0 || fixtureHasMatchLink(world, fixture)) used[fixture.id] = true;
    });
    (list || []).forEach(function(fixture, idx){
      if (!fixture) return;
      if (fixture.id && String(fixture.id).indexOf('fx:') === 0) { used[fixture.id] = true; return; }
      if (fixtureHasMatchLink(world, fixture)) { if (fixture.id) used[fixture.id] = true; return; }
      var base = stableFixtureId(world, fixture, idx);
      var next = base;
      var suffix = 1;
      while (used[next]) { suffix += 1; next = base + ':x' + fixtureIdPad(suffix, 2); }
      fixture.id = next;
      used[next] = true;
    });
    return list;
  }

  function escapeHtml(value){
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

