  function updateAppScale(){
    var shell = document.getElementById('app-shell');
    if (!shell) return;
    var baseWidth = 1760;
    var baseHeight = 990;
    var viewportWidth = window.innerWidth || document.documentElement.clientWidth || baseWidth;
    var viewportHeight = window.innerHeight || document.documentElement.clientHeight || baseHeight;
    var horizontalPadding = 20;
    var verticalPadding = 20;
    var availableWidth = Math.max(320, viewportWidth - horizontalPadding);
    var availableHeight = Math.max(240, viewportHeight - verticalPadding);
    var scale = Math.min(availableWidth / baseWidth, availableHeight / baseHeight);
    if (!isFinite(scale) || scale <= 0) scale = 1;
    scale = Math.min(1, scale);
    document.documentElement.style.setProperty('--app-scale', String(scale));
    shell.style.transform = 'scale(' + scale + ')';
    shell.style.transformOrigin = 'center center';
  }

