  var KF_SERVER_POLICY = Object.freeze({
    maxActiveTrainersPerUser: 5,
    maxHumanManagersPerWorld: 432
  });

  var WorldRecordByGameState = new WeakMap();
  var WorldRecordRegistry = new Map();

  function cloneSerializable(value){ return value == null ? value : JSON.parse(JSON.stringify(value)); }

  var WorldRepository = (function(){
    /* Development adapter for the future server repository contract. Persisted payloads are
       serialized bytes/strings, never a second mutable world object graph. */
    var records = new Map();
    return {
      save: function(record){ if(!record || !record.id) throw new Error('WorldRecord ohne ID'); records.set(String(record.id), JSON.stringify(record)); registerWorldRecord(record); return record.id; },
      load: function(worldId){ var payload=records.get(String(worldId)); if(!payload)return null; var record=JSON.parse(payload); registerWorldRecord(record); return record; },
      delete: function(worldId){ var key=String(worldId),record=WorldRecordRegistry.get(key)||null; if(record&&record.gameState)WorldRecordByGameState.delete(record.gameState); records.delete(key); WorldRecordRegistry.delete(key); RuntimeDerivedIndexByWorld.delete(key); return true; },
      listIds: function(){ return Array.from(records.keys()); },
      has: function(worldId){ return records.has(String(worldId)); }
    };
  })();

  var UserProfileRepository = (function(){
    var profiles = new Map();
    return {
      save: function(profile){ if(!profile || !profile.id) throw new Error('UserProfile ohne ID'); profiles.set(String(profile.id), JSON.stringify(profile)); return profile.id; },
      load: function(userId){ var payload=profiles.get(String(userId)); return payload ? JSON.parse(payload) : null; },
      has: function(userId){ return profiles.has(String(userId)); }
    };
  })();

