  function activeTrainerCount(profile){ return (((profile||{}).trainers||{}).order||[]).filter(function(id){ var t=profile.trainers.byId[id]; return t && t.status==='active'; }).length; }
  function trainerById(trainerId){ var p=AppState.userProfile; return p&&p.trainers&&p.trainers.byId ? p.trainers.byId[trainerId]||null : null; }
  function activeLocalTrainer(){ return trainerById(((AppState.session||{}).activeTrainerId)||null); }

  function createWorldRecord(options){
    options=options||{};
    var gameState=options.gameState || createEmptyWorld({seasonNumber:1});
    var worldId=String(((gameState.meta||{}).id)||options.id||uid('world'));
    gameState.meta=gameState.meta||{}; gameState.meta.id=worldId;
    var record={
      id:worldId,
      schemaVersion:'kf-world-record-0.27.2',
      gameVersion:KF_VERSION,
      createdAt:gameState.meta.createdAt || new Date().toISOString(),
      createdByUserId:options.createdByUserId || null,
      creationRules:cloneSerializable(options.creationRules || {startVariant:'classic',leagueConfiguration:'default',clubSelection:'manual'}),
      runtimeSettings:{roundDurationHours:null},
      progression:{status:'waiting',deadlineAt:null,readyTrainerIds:[],lastHumanActivityAt:new Date().toISOString()},
      memberships:{byTrainerId:{},order:[]},
      gameState:gameState
    };
    registerWorldRecord(record);
    return record;
  }

  function registerWorldRecord(record){
    if(!record||!record.id||!record.gameState)return record;
    WorldRecordRegistry.set(String(record.id),record);
    WorldRecordByGameState.set(record.gameState,record);
    return record;
  }

  function worldRecordForGameState(world){
    if(!world)return null;
    var direct=WorldRecordByGameState.get(world); if(direct)return direct;
    var id=String((((world||{}).meta||{}).id)||'');
    var record=id?WorldRecordRegistry.get(id):null;
    if(record&&record.gameState===world){WorldRecordByGameState.set(world,record);return record;}
    return null;
  }

  function activeMemberships(record){ return (((record||{}).memberships||{}).order||[]).map(function(id){return record.memberships.byTrainerId[id];}).filter(function(m){return m&&m.status==='active';}); }
  function membershipForTrainer(record,trainerId){ return record&&record.memberships&&record.memberships.byTrainerId ? record.memberships.byTrainerId[trainerId]||null : null; }
  function activeMembershipForClub(world,clubId){ var record=worldRecordForGameState(world); if(!record)return null; return activeMemberships(record).find(function(m){return m.clubId===clubId;})||null; }

  function createTrainerForWorld(profile,record,options){
    options=options||{};
    if(!profile||!record)return {ok:false,message:'Profil oder Welt fehlt.'};
    if(activeTrainerCount(profile)>=Number((profile.trainers||{}).maxActive||KF_SERVER_POLICY.maxActiveTrainersPerUser))return {ok:false,message:'Alle Trainerplaetze sind belegt.'};
    var existing=(((profile||{}).trainers||{}).order||[]).map(function(id){return profile.trainers.byId[id];}).find(function(t){return t&&t.status==='active'&&t.worldId===record.id;});
    var existingMembership=activeMemberships(record).find(function(m){return m.userProfileId===profile.id;});
    if(existing||existingMembership)return {ok:false,message:'Dieses Benutzerprofil hat bereits einen aktiven Trainer in dieser Welt.'};
    if(activeMemberships(record).length>=KF_SERVER_POLICY.maxHumanManagersPerWorld)return {ok:false,message:'Diese Welt hat bereits die maximale Anzahl menschlicher Trainer.'};
    var trainer={id:uid('trainer'),userProfileId:profile.id,worldId:record.id,displayName:options.displayName||profile.displayName||'Trainer',createdAt:new Date().toISOString(),status:'active',level:1,xp:0,reputation:0};
    profile.trainers.byId[trainer.id]=trainer; profile.trainers.order.push(trainer.id);
    record.memberships.byTrainerId[trainer.id]={trainerId:trainer.id,userProfileId:profile.id,clubId:null,status:'active',joinedAt:new Date().toISOString(),lastActivityAt:new Date().toISOString(),trainerDisplayName:trainer.displayName};
    record.memberships.order.push(trainer.id);
    profile.lifetimeStats.worldsJoined=Number(profile.lifetimeStats.worldsJoined||0)+1;
    registerWorldRecord(record);
    return {ok:true,trainer:trainer,membership:record.memberships.byTrainerId[trainer.id]};
  }

  function removeTrainerFromWorld(profile,record,trainerId,options){
    options=options||{}; var trainer=profile&&profile.trainers&&profile.trainers.byId?profile.trainers.byId[trainerId]:null; var membership=membershipForTrainer(record,trainerId);
    if(!trainer||!membership)return {ok:false,message:'Trainerbindung nicht gefunden.'};
    if(options.archive!==false){ profile.pastTrainerCareers.push({trainerId:trainer.id,trainerName:trainer.displayName,worldId:record.id,endedAt:new Date().toISOString(),reason:options.reason||'ended',level:Number(trainer.level||1),xp:Number(trainer.xp||0)}); profile.lifetimeStats.completedTrainerCareers=Number(profile.lifetimeStats.completedTrainerCareers||0)+1; }
    delete profile.trainers.byId[trainerId]; profile.trainers.order=profile.trainers.order.filter(function(id){return id!==trainerId;});
    delete record.memberships.byTrainerId[trainerId]; record.memberships.order=record.memberships.order.filter(function(id){return id!==trainerId;});
    var worldEmpty=activeMemberships(record).length===0;
    if(worldEmpty && options.deleteWorldIfEmpty!==false) WorldRepository.delete(record.id);
    return {ok:true,worldEmpty:worldEmpty};
  }

  function assignTrainerClub(record,trainerId,clubId){
    if(!record||!record.gameState)return {ok:false,message:'Welt fehlt.'};
    var membership=membershipForTrainer(record,trainerId); if(!membership||membership.status!=='active')return {ok:false,message:'Keine aktive Trainerteilnahme.'};
    if(!record.gameState.clubs||!record.gameState.clubs.byId||!record.gameState.clubs.byId[clubId])return {ok:false,message:'Verein existiert nicht.'};
    var occupied=activeMemberships(record).find(function(m){return m.clubId===clubId&&m.trainerId!==trainerId;}); if(occupied)return {ok:false,message:'Der Verein wird bereits von einem menschlichen Trainer gesteuert.'};
    membership.clubId=clubId; membership.lastActivityAt=new Date().toISOString(); record.progression.lastHumanActivityAt=membership.lastActivityAt;
    return {ok:true,membership:membership};
  }

  function executeWorldCommand(record,command){
    command=command||{};
    if(!record||!record.gameState)return {ok:false,message:'Keine Welt geladen.'};
    if(command.type==='ASSIGN_TRAINER_CLUB')return assignTrainerClub(record,command.actorTrainerId,command.clubId);
    if(command.type==='SET_FORMATION'){
      var membership=membershipForTrainer(record,command.actorTrainerId); if(!membership||membership.clubId!==command.clubId)return {ok:false,message:'Keine Berechtigung fuer diesen Verein.'};
      var club=record.gameState.clubs.byId[command.clubId],squad=record.gameState.squads[command.clubId]; if(!club||!squad)return {ok:false,message:'Kader nicht gefunden.'}; applyLineupFormation(club,squad,record.gameState,command.formationKey); membership.lastActivityAt=new Date().toISOString(); record.progression.lastHumanActivityAt=membership.lastActivityAt; return {ok:true};
    }
    if(command.type==='SET_TACTIC'){
      var tacticMembership=membershipForTrainer(record,command.actorTrainerId); if(!tacticMembership||tacticMembership.clubId!==command.clubId)return {ok:false,message:'Keine Berechtigung fuer diesen Verein.'};
      if(!LINEUP_TACTIC_DEFS[command.kind])return {ok:false,message:'Unbekannte Taktikeinstellung.'};
      var tacticSquad=record.gameState.squads[command.clubId]; if(!tacticSquad)return {ok:false,message:'Kader nicht gefunden.'}; ensureSquadTactics(tacticSquad); tacticSquad.tactics[command.kind]=tacticValueNumber(command.kind,command.value); tacticMembership.lastActivityAt=new Date().toISOString(); record.progression.lastHumanActivityAt=tacticMembership.lastActivityAt; return {ok:true};
    }
    return {ok:false,message:'Unbekannter World-Command.'};
  }

  function migrateLegacyWorldToRecord(world,profile){
    if(!world)return null;
    var legacyControl=world.control||null; delete world.control;
    if(world.meta){delete world.meta.mode;delete world.meta.sourceSessionId;world.meta.schemaVersion='kf-core-0.25.1';}
    var record=createWorldRecord({gameState:world,createdByUserId:profile&&profile.id||null});
    if(legacyControl&&profile){
      var humanClubIds=Object.keys(legacyControl.controllerTypes||{}).filter(function(clubId){return legacyControl.controllerTypes[clubId]==='human';});
      if(humanClubIds.length){var result=createTrainerForWorld(profile,record,{displayName:profile.displayName||'Trainer'});if(result.ok)assignTrainerClub(record,result.trainer.id,humanClubIds[0]);}
    }
    return record;
  }

