  function preferredCountry(world){
    if (!world || !world.clubs || !world.clubs.order.length) return null;
    return world.clubs.byId[world.clubs.order[0]].countryName || null;
  }

  function leagueKeysForCountry(world, countryName){
    var map = {};
    if (!world || !countryName) return [];
    world.clubs.order.forEach(function(clubId){
      var club = world.clubs.byId[clubId];
      if (club.countryName === countryName) map[club.leagueKey] = true;
    });
    return Object.keys(map).sort(function(a,b){ return a.localeCompare(b, 'de'); });
  }


function clubsForSelection(world, countryName, leagueKey){
  if (!world) return [];
  return world.clubs.order.map(function(clubId){ return world.clubs.byId[clubId]; }).filter(function(club){
    return (!countryName || club.countryName === countryName) && (!leagueKey || club.leagueKey === leagueKey);
  }).sort(function(a,b){ return clubSortKey(a).localeCompare(clubSortKey(b), 'de') || a.name.localeCompare(b.name, 'de'); });
}


function averageOverall(world, playerIds){
  if (!playerIds || !playerIds.length) return 0;
  var total = 0;
  playerIds.forEach(function(playerId){ var player = world.players.byId[playerId]; total += Number((player && calculatePlayerCurrentOverallAdvanced(player)) || (player && player.overall) || 0); });
  return Math.round(total / playerIds.length);
}

function clubSortKey(club){
  if (!club) return '';
  var name = String(club.name || '').trim();
  var tokens = name.replace(/[^\p{L}\p{N}\s-]/gu,' ').split(/\s+/).filter(Boolean);
  if (!tokens.length) return name.toLowerCase();
  tokens.sort(function(a,b){ return b.length - a.length || a.localeCompare(b,'de'); });
  return (tokens[0] || name).toLowerCase();
}


