  if (shape === 'shield') return '<path d="M62 45 H238 V126 C238 184 202 230 150 254 C98 230 62 184 62 126 Z" />';
  if (shape === 'hexagon') return '<path d="M90 42 H210 L267 150 L210 258 H90 L33 150 Z" />';
  if (shape === 'diamond') return '<path d="M150 32 L268 150 L150 268 L32 150 Z" />';
  if (shape === 'oval') return '<ellipse cx="150" cy="150" rx="124" ry="94" />';
  if (shape === 'doubleRing') return '<circle cx="150" cy="150" r="112" />';
  if (shape === 'verticalBadge') return '<rect x="78" y="30" width="144" height="240" rx="62" />';
  if (shape === 'ticketShape') return '<path d="M34 72 H266 V120 C248 120 236 132 236 150 C236 168 248 180 266 180 V228 H34 V180 C52 180 64 168 64 150 C64 132 52 120 34 120 Z" />';
