function activeClub(){
  var world = AppState.world;
  var activeId = AppState.session && AppState.session.activeClubId;
  return world && activeId && world.clubs && world.clubs.byId ? world.clubs.byId[activeId] : null;
}

function activeSquad(){
  var club = activeClub();
  var squad = club && AppState.world && AppState.world.squads ? (AppState.world.squads[club.id] || { playerIds: [] }) : { playerIds: [] };
  var hasMaskState = !!(squad && squad.lineupMaskState && squad.lineupMaskState.playerPlacementById);
  if (club && AppState.world && !squad.manualLineup && !hasMaskState) optimizeSquadAssignmentsForClub(club, squad, AppState.world);
  return squad;
}

function shirtNumberForPlayer(player){
  return player && player.shirtNumber != null ? player.shirtNumber : null;
}

function playerSupportsPosition(player, position){
  if (!player || !position) return false;
  return player.mainPosition === position || player.secondaryPosition1 === position || player.secondaryPosition2 === position;
}

function playerPositionFitScore(player, position){
  if (!player || !position) return -99999;
  var overall = Number(calculatePlayerCurrentOverallAdvanced(player) || player.overall || 0);
  var form = Number(player.form || 0);
  var fitness = Number(player.fitness || 0);
  if (player.mainPosition === position) return overall * 100 + form + (fitness / 4) + 18;
  if (player.secondaryPosition1 === position || player.secondaryPosition2 === position) return overall * 100 + form + (fitness / 4) + 6;
  return -99999;
}

function optimizeSquadAssignmentsForClub(club, squad, world){
  if (!club || !squad || !world || !world.players || !world.players.byId) return squad;
  var formationKey = currentSquadFormationKey(world, club);
  var formation = formationLookup()[formationKey] || {};
  var slots = orderedFormationSlots(formationKey);
  var playerIds = (squad.playerIds || []).slice();
  if (!playerIds.length || !slots.length || !formation.positionMap) return squad;
  var available = playerIds.slice();
  var lineup = [];
  slots.forEach(function(slotId){
    var wantedPosition = formation.positionMap[slotId];
    var bestIndex = -1;
    var bestScore = -999999;
    available.forEach(function(id, index){
      var player = world.players.byId[id];
      if (!player || player.mainPosition === 'TW') return;
      var score = playerPositionFitScore(player, wantedPosition);
      if (score > bestScore) {
        bestScore = score;
        bestIndex = index;
      }
    });
    if (bestIndex < 0 && available.length) {
      available.forEach(function(id, index){
        var player = world.players.byId[id];
        if (!player || player.mainPosition === 'TW') return;
        var fallbackScore = Number((player && player.overall) || 0) * 100 + Number((player && player.form) || 0) + Number((player && player.fitness) || 0) / 4;
        if (fallbackScore > bestScore) {
          bestScore = fallbackScore;
          bestIndex = index;
        }
      });
    }
    if (bestIndex > -1) lineup.push(available.splice(bestIndex, 1)[0]);
  });
  var benchSize = Array.isArray(squad.bench) && squad.bench.length ? squad.bench.length : ((((DBData.db2Rules || {}).squad || {}).benchSize) || 7);
  available.sort(function(aId, bId){
    var a = world.players.byId[aId] || {};
    var b = world.players.byId[bId] || {};
    return (Number(b.overall || 0) - Number(a.overall || 0)) || (Number(b.form || 0) - Number(a.form || 0)) || String(a.fullName || '').localeCompare(String(b.fullName || ''), 'de');
  });
  squad.lineup = lineup;
  squad.bench = available.slice(0, benchSize);
  squad.reserve = available.slice(benchSize);
  return squad;
}

function slotLaneOrder(slotId){
  if (!slotId) return 99;
  var lane = String(slotId).split('_').pop();
  return ({ l:0, lz:1, z:2, rz:3, r:4 })[lane] != null ? ({ l:0, lz:1, z:2, rz:3, r:4 })[lane] : 99;
}

function slotVerticalOrder(slotId){
  if (!slotId) return 999;
  var parts = String(slotId).split('_');
  var group = parts[0] || '';
  var alignment = parts[1] || 'basic';
  var map = {
    goal: { basic: 890 },
    defense: { basic: 770, off: 700 },
    midfield: { def: 560, basic: 490, off: 420 },
    attack: { def: 280, basic: 210, off: 140 }
  };
  return map[group] && map[group][alignment] != null ? map[group][alignment] : 999;
}

function orderedFormationSlots(formationKey){
  var formation = formationLookup()[formationKey] || {};
  var map = formation.positionMap || {};
  return Object.keys(map).filter(function(slotId){ return slotId !== 'goal_basic_z'; }).sort(function(a, b){
    var primary = slotVerticalOrder(b) - slotVerticalOrder(a);
    if (primary) return primary;
    return slotLaneOrder(a) - slotLaneOrder(b);
  });
}

function assignedPositionForPlayer(club, squad, playerId){
  if (!club || !squad) return '-';
  ensureLineupMaskState(club, squad, AppState.world);
  var info = lineupPlacementForPlayer(squad, playerId);
  if (info && info.location === 'field') {
    if (info.slot === 'goal_basic_z') return 'TW';
    return (LINEUP_GRID_BY_ID[info.slot] || {}).role || 'Startelf';
  }
  if (info && info.location === 'bench') return 'Bank';
  return 'Reserve';
}

function usageSortValueForPlayer(club, squad, playerId){
  ensureLineupMaskState(club, squad, AppState.world);
  var info = lineupPlacementForPlayer(squad, playerId);
  if (info && info.location === 'field') return lineupDisplaySortValue(info.slot);
  if (info && info.location === 'bench') {
    var idx = LINEUP_BENCH_SLOTS.indexOf(info.slot);
    return 1000 + (idx > -1 ? idx : 99);
  }
  return 2000;
}

function usageStateForPlayer(squad, playerId){
  if (!squad) return 'reserve';
  ensureLineupMaskState(activeClub(), squad, AppState.world);
  var info = lineupPlacementForPlayer(squad, playerId);
  if (info && info.location === 'field') return 'field';
  if (info && info.location === 'bench') return 'bench';
  return 'reserve';
}

function maxTextLength(values){
  return (values || []).reduce(function(max, value){
    var len = String(value == null ? '' : value).length;
    return len > max ? len : max;
  }, 0);
}

function textWidthPx(values, minPx, maxPx, perChar){
  var px = Math.ceil(maxTextLength(values) * (perChar || 7.2) + 18);
  return Math.max(minPx || 32, Math.min(maxPx || 240, px));
}

function buildSquadGridConfig(world, club, squad, ids){
  var playerIds = (ids || squad && squad.playerIds || []).slice();
  var players = playerIds.map(function(id){ return (world && world.players && world.players.byId && world.players.byId[id]) || {}; });
  var usageW = textWidthPx(playerIds.map(function(id){ return assignedPositionForPlayer(club, squad, id); }).concat(['Ein.', 'Reserve']), 76, 102, 7);
  var nrW = textWidthPx(players.map(function(player){ return shirtNumberForPlayer(player) || '-'; }).concat(['Nr.']), 46, 58, 7);
  var nameMin = textWidthPx(players.map(function(player){ return player.fullName || ''; }).concat(['Spieler']), 160, 240, 7.4);
  var natMin = textWidthPx(players.map(function(player){ return player.nationality || '-'; }).concat(['Nat.']), 92, 132, 7);
  var nposMin = textWidthPx(players.map(function(player){ return [player.secondaryPosition1, player.secondaryPosition2].filter(Boolean).join(', ') || '-'; }).concat(['NPos.']), 90, 120, 7);
  var charMin = textWidthPx(players.map(function(player){ return prettifyKeyLabel(player.character1 || '-'); }).concat(players.map(function(player){ return prettifyKeyLabel(player.character2 || '-'); }), ['Char.']), 82, 108, 7);
  var typeMin = textWidthPx(players.map(function(player){ return prettifyKeyLabel(player.playerType1 || '-'); }).concat(players.map(function(player){ return prettifyKeyLabel(player.playerType2 || '-'); }), ['Typ.']), 92, 116, 7);
  var footW = textWidthPx(players.map(function(player){ return displayFootLabel(player.strongFoot); }).concat(['Fuß']), 58, 72, 7);
  var moneyW = textWidthPx(players.map(function(player){ return formatSquadCurrency(player.marketValue || 0); }).concat(players.map(function(player){ return formatSquadCurrency(playerContractBaseSalary(player)); }), ['MW','Geh.']), 84, 102, 7);
  return {
    usage: usageW,
    nr: nrW,
    nameMin: nameMin,
    template: [
      usageW + 'px',
      nrW + 'px',
      'minmax(' + nameMin + 'px,1.25fr)',
      '48px',
      'minmax(' + natMin + 'px,.9fr)',
      '52px',
      'minmax(' + nposMin + 'px,.82fr)',
      '50px','50px','48px','52px',
      'minmax(' + charMin + 'px,.78fr)',
      'minmax(' + charMin + 'px,.78fr)',
      'minmax(' + typeMin + 'px,.84fr)',
      'minmax(' + typeMin + 'px,.84fr)',
      footW + 'px',
      '54px',
      moneyW + 'px',
      moneyW + 'px'
    ].join(' ')
  };
}

function buildLineupGridTemplate(world, club, squad, ids){
  var playerIds = (ids || squad && squad.playerIds || []).slice();
  var players = playerIds.map(function(id){ return (world && world.players && world.players.byId && world.players.byId[id]) || {}; });
  var usageVals = playerIds.map(function(id){ return assignedPositionForPlayer(club, squad, id); }).concat(['Ein.','Reserve']);
  var nrVals = players.map(function(player){ return shirtNumberForPlayer(player) || '-'; }).concat(['Nr.']);
  var nameVals = players.map(function(player){ return player.fullName || ''; }).concat(['Spieler']);
  var nposVals = players.map(function(player){ return [player.secondaryPosition1, player.secondaryPosition2].filter(Boolean).join(', ') || '-'; }).concat(['NPos.']);
  return [
    textWidthPx(usageVals, 62, 84, 7),
    textWidthPx(nrVals, 40, 48, 7),
    'minmax(' + textWidthPx(nameVals, 128, 176, 7.1) + 'px,1.18fr)',
    '46px',
    'minmax(' + textWidthPx(nposVals, 72, 102, 7) + 'px,.88fr)',
    '38px','40px','42px','46px'
  ].join(' ');
}

function buildCompactGridTemplate(world, club, squad, ids){
  var playerIds = (ids || squad && squad.playerIds || []).slice();
  var players = playerIds.map(function(id){ return (world && world.players && world.players.byId && world.players.byId[id]) || {}; });
  var usageVals = playerIds.map(function(id){ return assignedPositionForPlayer(club, squad, id); }).concat(['Ein.','Reserve']);
  var nrVals = players.map(function(player){ return shirtNumberForPlayer(player) || '-'; }).concat(['Nr.']);
  var nameVals = players.map(function(player){ return player.fullName || ''; }).concat(['Spieler']);
  var nposVals = players.map(function(player){ return [player.secondaryPosition1, player.secondaryPosition2].filter(Boolean).join(', ') || '-'; }).concat(['NPos.']);
  var moneyVals = players.map(function(player){ return formatSquadCurrency(player.marketValue || 0); }).concat(players.map(function(player){ return formatSquadCurrency(playerContractBaseSalary(player)); }), ['MW','Geh.']);
  return [
    textWidthPx(usageVals, 62, 82, 7),
    textWidthPx(nrVals, 42, 48, 7),
    'minmax(' + textWidthPx(nameVals, 130, 180, 7.1) + 'px,1.3fr)',
    '46px',
    'minmax(' + textWidthPx(nposVals, 78, 102, 7) + 'px,.95fr)',
    '48px','56px',textWidthPx(moneyVals, 84, 102, 7),textWidthPx(moneyVals, 84, 102, 7)
  ].join(' ');
}

function locatePlayerInSquad(squad, playerId){
  if (!squad || !playerId) return { type:'reserve', index:-1 };
  var li = (squad.lineup || []).indexOf(playerId);
  if (li > -1) return { type:'field', index:li };
  var bi = (squad.bench || []).indexOf(playerId);
  if (bi > -1) return { type:'bench', index:bi };
  var ri = (squad.reserve || []).indexOf(playerId);
  return { type:'reserve', index:ri };
}

function handleLineupDrop(playerId, targetType, targetValue){
  var club = activeClub();
  var squad = activeSquad();
  var world = AppState.world;
  if (!club || !squad || !world || !playerId) return;
  ensureLineupMaskState(club, squad, world);
  var placement = squad.lineupMaskState.playerPlacementById || {};
  var source = placement[playerId] || { location:'reserve', slot:null };
  function countField(){ return Object.keys(placement).filter(function(id){ return placement[id] && placement[id].location === 'field'; }).length; }
  function move(id, location, slot){ placement[id] = { location:location, slot:slot == null ? null : String(slot) }; }
  if (targetType === 'row') {
    var targetPlayerId = String(targetValue || '');
    if (!targetPlayerId || targetPlayerId === playerId || !placement[targetPlayerId]) return;
    var targetPlacement = placement[targetPlayerId];
    placement[targetPlayerId] = { location:source.location, slot:source.slot };
    placement[playerId] = { location:targetPlacement.location, slot:targetPlacement.slot };
  } else if (targetType === 'field') {
    var slotId = String(targetValue || '');
    if (!slotId) return;
    var occupantId = lineupPlayerAt(squad, 'field', slotId);
    if (!occupantId && source.location !== 'field' && countField() >= 11) return;
    if (occupantId && occupantId !== playerId) move(occupantId, source.location || 'reserve', source.slot || null);
    move(playerId, 'field', slotId);
  } else if (targetType === 'bench') {
    var benchSlot = 'bench_' + String(targetValue || '0');
    var benchOccupant = lineupPlayerAt(squad, 'bench', benchSlot);
    if (benchOccupant && benchOccupant !== playerId) move(benchOccupant, source.location || 'reserve', source.slot || null);
    move(playerId, 'bench', benchSlot);
  } else {
    move(playerId, 'reserve', null);
  }
  syncSquadFromLineupMaskState(club, squad, world);
  renderApp();
}


function positionDisplayOrder(position){
  var map = { TW:0, LV:1, IV:2, RV:4, DM:5, ZM:6, LM:7, RM:8, OM:9, LF:10, ST:11, RF:12, HS:10 };
  return map[position] != null ? map[position] : 99;
}

function tooltipAttr(label){
  return ' title="' + escapeHtml(label) + '"';
}

function prettifyKeyLabel(value){
  if (!value) return '-';
  var raw = String(value).replace(/_/g, ' ').replace(/-/g, ' ');
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

function iconInitials(value){
  var label = prettifyKeyLabel(value);
  if (!label || label === '-') return '–';
  var parts = label.split(/\s+/).filter(Boolean);
  if (!parts.length) return '–';
  if (parts.length === 1) return parts[0].slice(0,2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

function iconPlaceholder(value, kind){
  var label = prettifyKeyLabel(value);
  return '<span class="player-icon-placeholder player-icon-' + escapeHtml(kind || 'generic') + '"' + tooltipAttr(label) + '>' + escapeHtml(iconInitials(value)) + '</span>';
}

