function playerProfileIconMarkup(value, kind){
  var key = kind === 'character' ? normalizeCharacterKey(value) : normalizePlayerTypeKey(value);
  var label = prettifyKeyLabel(value);
  var iconPath = kind === 'character' ? PLAYER_PROFILE_CHARACTER_ICON_MAP[key] : PLAYER_PROFILE_TYPE_ICON_MAP[key];
  if (iconPath) {
    return '<span class="player-icon-placeholder player-icon-' + escapeHtml(kind || 'generic') + '"' + tooltipAttr(label) + '><img src="' + escapeHtml(iconPath) + '" alt="" loading="lazy"></span>';
  }
  return '<span class="player-icon-placeholder player-icon-' + escapeHtml(kind || 'generic') + '"' + tooltipAttr(label) + '>' + escapeHtml(iconInitials(value)) + '</span>';
}

function playerSkillModifierData(player, attributeKey){
  var entries = [];
  var total = 0;
  [
    { key: normalizeCharacterKey((player && player.character1) || ''), label: prettifyKeyLabel((player && player.character1) || ''), map: PLAYER_PROFILE_EFFECT_MAPS.characters, source: 'Charakter' },
    { key: normalizeCharacterKey((player && player.character2) || ''), label: prettifyKeyLabel((player && player.character2) || ''), map: PLAYER_PROFILE_EFFECT_MAPS.characters, source: 'Charakter' },
    { key: normalizePlayerTypeKey((player && player.playerType1) || ''), label: prettifyKeyLabel((player && player.playerType1) || ''), map: PLAYER_PROFILE_EFFECT_MAPS.types, source: 'Spielertyp' },
    { key: normalizePlayerTypeKey((player && player.playerType2) || ''), label: prettifyKeyLabel((player && player.playerType2) || ''), map: PLAYER_PROFILE_EFFECT_MAPS.types, source: 'Spielertyp' }
  ].forEach(function(item){
    if (!item.key || !item.map[item.key]) return;
    var delta = Number(item.map[item.key][attributeKey] || 0);
    if (!delta) return;
    total += delta;
    entries.push((delta > 0 ? '+' : '') + delta + ' ' + item.source + ': ' + item.label);
  });
  return { total: total, entries: entries };
}

function playerIssueCount(player, keys){
  if (!player || !keys || !keys.length) return 0;
  for (var i = 0; i < keys.length; i += 1) {
    var raw = player[keys[i]];
    if (raw == null || raw === '' || raw === false) continue;
    var num = Number(raw);
    if (!isNaN(num) && isFinite(num) && num > 0) return num;
    if (raw === true) return 1;
  }
  return 0;
}

function renderPlayerStatusBox(player){
  var injuryCount = playerIssueCount(player, ['injuryMatchesLeft','injuryWeeksLeft','injuryDaysLeft','injuryGamesLeft','injuryCount','injured']);
  var suspensionCount = playerIssueCount(player, ['suspensionMatchesLeft','suspensionGamesLeft','suspensionCount','suspended']);
  var label = 'Verfügbar';
  if (injuryCount > 0 && suspensionCount > 0) label = 'Verletzt & gesperrt';
  else if (injuryCount > 0) label = 'Verletzt';
  else if (suspensionCount > 0) label = 'Gesperrt';
  return '' +
    '<div class="player-status-line"><span class="player-status-text">' + escapeHtml(label) + '</span></div>' +
    '<div class="player-status-icons">' +
      '<span class="player-status-icon' + (injuryCount > 0 ? ' is-alert' : '') + '"' + tooltipAttr(injuryCount > 0 ? 'Verletzung (' + injuryCount + ')' : 'Keine Verletzung') + '>✚</span>' +
      '<span class="player-status-icon' + (suspensionCount > 0 ? ' is-alert' : '') + '"' + tooltipAttr(suspensionCount > 0 ? 'Sperre (' + suspensionCount + ')' : 'Keine Sperre') + '>⛔</span>' +
    '</div>';
}

function displayFootLabel(value){
  if (!value) return '-';
  var map = { left:'Links', right:'Rechts', both:'Beidfüßig', links:'Links', rechts:'Rechts' };
  return map[String(value).toLowerCase()] || prettifyKeyLabel(value);
}

function talentStarsValueFromDisplayedTalent(value){
  var points = Math.max(1, Math.min(10, Number(value) || 1));
  return points / 2;
}
function talentStarsTextFromDisplayedTalent(value){
  var stars = talentStarsValueFromDisplayedTalent(value);
  return String(stars).replace('.', ',') + '★';
}
function starsLineFromDisplayedTalent(value){
  var points = Math.max(1, Math.min(10, Number(value) || 1));
  var stars = talentStarsValueFromDisplayedTalent(points);
  var full = Math.floor(stars);
  var half = (stars - full) >= 0.5 ? 1 : 0;
  var empty = Math.max(0, 5 - full - half);
  var label = String(stars).replace('.', ',') + ' Sterne';
  var html = '<div class="talent-stars" aria-label="Talent ' + escapeHtml(label) + '">';
  for (var i=0;i<full;i++) html += '<span class="star full">★</span>';
  if (half) html += '<span class="star half">★</span>';
  for (var j=0;j<empty;j++) html += '<span class="star empty">☆</span>';
  html += '<span class="talent-points">' + escapeHtml(label) + '</span></div>';
  return html;
}


