  if (showDropdown) {
    var options = playerCompetitionStatsOptions(world, player && player.id).map(function(option){ return { value:option.value, label:option.label, selected: option.value === selection }; });
    var current = (options.find(function(option){ return option.selected; }) || options[0] || { label:'Aktuelle Saison' }).label;
    dropdown = '<div class="club-profile-stats-dropdown">' + renderProfileDropdown('player-profile-stats-season-select', current, options) + '</div>';
  }
