function formatMillions(value){
  var num = Number(value || 0);
  if (!Number.isFinite(num)) num = 0;
  var rounded = Math.round(num * 1000) / 1000;
  var abs = Math.abs(rounded);
  var sign = rounded < 0 ? '-' : '';
  if (abs < 1) {
    var k = Math.round(abs * 1000);
    return sign + String(k).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' K €';
  }
  return sign + abs.toFixed(3).replace('.', ',') + ' Mio. €';
}

function formatNumber(value){
  return String(value == null ? '' : value).replace('.', ',');
}

function formatWeekLabel(slot){
  if (!slot) return 'Mitte 1 von 52';
  return slot.phase + ' ' + slot.week + ' von 52';
}

function currentCalendarSlot(world){
  if (!world || !world.calendar) return null;
  var key = world.calendar.currentSlotKey;
  var slots = world.calendar.slots || [];
  for (var i=0;i<slots.length;i++) if (slots[i].key === key) return slots[i];
  return slots[0] || null;
}

function nextCalendarSlot(world){
  if (!world || !world.calendar || !world.calendar.slots) return null;
  var slots = world.calendar.slots || [];
  var currentIndex = slotIndexForKey(world, ((world||{}).calendar||{}).currentSlotKey);
  if (currentIndex === 9999) return slots[0] || null;
  return slots[currentIndex + 1] || null;
}


