    logoConcept:options.logoConcept || brand.concept || sponsorLogoConceptFromSponsor({ id:id, name:fullName, displayName:displayName, legalForm:legalForm, categoryKey:cat.key, categoryLabel:cat.label, size:size, city:city, countryName:countryName, logoSeed:seed, logoText:displayName, logoSubline:'' }),
    logoShape:options.logoShape || brand.shape,
