  if (fixture.competition === 'league') return fixture.leagueKey || fixture.competitionLabel || 'Liga';
  if (fixture.competition === 'cup' || fixture.competition === 'national-cup') return fixture.countryName ? (fixture.countryName + ' · Nationaler Pokal') : 'Nationaler Pokal';
  if (fixture.competition === 'fiebercup') return 'Fieber-Cup';
  return fixture.competitionLabel || fixture.competition || '-';
