  if (level === 1) return { title:'1. Liga', champion:[1], fieberCup:[1,2,3], optionalFieberCup:[4,5,6], relegation:[16], directRelegation:[17,18], directPromotion:[], lowerRelegation:[16], promotionPlayoff:[] };
