function rowMarkerTextForLeague(world, leagueKey, row){
  var context = previousSeasonMarkerContext(world, leagueKey);
  var markers = [];
  var clubId = row && row.clubId;
  if (context && row) {
    var wasPromoted = context.directPromotionClubIds.indexOf(clubId) !== -1;
    if (context.championClubIds.indexOf(clubId) !== -1 && !wasPromoted) markers.push('M');
    if (context.cupWinnerClubId === clubId) markers.push('P');
    if (context.fieberWinnerClubId === clubId) markers.push('F');
    if (wasPromoted) markers.push('A');
    if (context.directRelegationClubIds.indexOf(clubId) !== -1) markers.push('Ab');
  }
  if (isLeagueThreeCupQualificationRow(world, leagueKey, row)) markers.push('Pokal');
  return markers.length ? (' (' + markers.join(', ') + ')') : '';
}


function rowOutcomeClassForLeague(world, leagueKey, row){
  var context = buildSeasonOutcomeContext(world, leagueKey);
  var classes = [];
  if (context && row) {
    var clubId = row.clubId;
    if (context.championClubIds.indexOf(clubId) !== -1) classes.push('outcome-champion');
    if (context.fieberCupClubIds.indexOf(clubId) !== -1) classes.push('outcome-fiebercup');
    if (context.optionalFieberCupClubIds.indexOf(clubId) !== -1) classes.push('outcome-fiebercup-optional');
    if (context.relegationClubIds.indexOf(clubId) !== -1 || context.promotionPlayoffClubIds.indexOf(clubId) !== -1) classes.push('outcome-relegation');
    if (context.directRelegationClubIds.indexOf(clubId) !== -1) classes.push('outcome-relegated');
    if (context.directPromotionClubIds.indexOf(clubId) !== -1) classes.push('outcome-promoted');
  }
  if (isLeagueThreeCupQualificationRow(world, leagueKey, row)) classes.push('outcome-national-cup');
  return classes.length ? (' ' + classes.join(' ')) : '';
}

