      var lowerRows = standings[lower.leagueKey] || [];
      var upper16 = upperRows.find(function(entry){ return Number(entry.position || 0) === 16; });
      var lower3 = lowerRows.find(function(entry){ return Number(entry.position || 0) === 3; });
