    ownCondition: conditionAveragesForPlayerIds(world, clubFieldPlayerIdsFromLineupState(world, club.id)),
    opponentCondition: opponent ? conditionAveragesForPlayerIds(world, probableLineupIdsForClub(world, opponent.id, fixture.competition)) : null,
    ownChemistry: calculateTeamChemistry(world, club.id, null),
    opponentChemistry: opponent ? calculateTeamChemistry(world, opponent.id, { lineupIds: probableLineupIdsForClub(world, opponent.id, fixture.competition) }) : null,
    ownFormLine: recentFormStringForClub(world, club.id, 5),
    opponentFormLine: opponent ? recentFormStringForClub(world, opponent.id, 5) : '-',
    ownUnavailableCount: clubUnavailableCount(world, club.id, fixture.competition),
    opponentUnavailableCount: opponent ? clubUnavailableCount(world, opponent.id, fixture.competition) : 0,
