function leagueTableSortValue(row, key){
  if (key === 'position') return Number(row.position || 0);
  if (key === 'name') return String(row.name || '').toLowerCase();
  if (key === 'games') return Number(row.games || 0);
  if (key === 'wins') return Number(row.wins || 0);
  if (key === 'draws') return Number(row.draws || 0);
  if (key === 'losses') return Number(row.losses || 0);
  if (key === 'gf') return Number(row.goalsFor || 0);
  if (key === 'ga') return Number(row.goalsAgainst || 0);
  if (key === 'diff') return Number(row.diff || 0);
  if (key === 'yellow') return Number(row.yellow || 0);
  if (key === 'yellowRed') return Number(row.yellowRed || 0);
  if (key === 'red') return Number(row.red || 0);
  if (key === 'points') return Number(row.points || 0);
  return Number(row.position || 0);
}

function sortLeagueTableRows(rows, key, dir){
  var direction = dir === 'asc' ? 1 : -1;
  return rows.slice().sort(function(a,b){
    var primary = leagueTableSortValue(a, key);
    var secondary = leagueTableSortValue(b, key);
    var cmp = compareSquadValues(primary, secondary);
    if (cmp !== 0) return cmp * direction;
    return compareSquadValues(Number(a.position || 0), Number(b.position || 0));
  });
}

function leagueTableHead(scope, currentKey, currentDir, label, key, fullLabel){
  var active = currentKey === key;
  var marker = active ? (currentDir === 'asc' ? ' ↑' : ' ↓') : '';
  return '<button class="squad-head-btn'+(active ? ' is-active' : '')+'" type="button" data-action="league-table-sort" data-scope="'+ escapeHtml(scope) +'" data-sort="'+ escapeHtml(key) +'"' + tooltipAttr(fullLabel || label) + '>' + escapeHtml(label) + marker + '</button>';
}


