      if (col.key === 'crest') return '<td class="align-center"><button class="table-crest-btn" type="button" data-action="open-club-profile" data-club-id="' + escapeHtml(row.clubId) + '"><img src="' + escapeHtml(row.crest) + '" alt="' + escapeHtml(row.name) + ' Wappen"'+onErrorFallbackAttr(crestFallbackAsset())+'></button></td>';
