function leagueSeasonOptionItems(world){
  return [{ value:'current', label:'Aktuelle Saison' }].concat(availableSeasonKeys(world).map(function(key){ return { value:key, label:'Saison ' + key }; })).concat([{ value:'all', label:'Gesamt' }]);
}

function expectedLeagueGamesForStats(world, leagueKey, seasonKey){
  if (!world || !leagueKey) return 0;
  if (seasonKey === 'all') return 0;
  if (seasonKey && seasonKey !== 'current') {
    var store = (((seasonStandingsStore(world)||{})[seasonKey]||{})[leagueKey]) || [];
    if (store.length) return Number(store[0].games || 0);
  }
  var clubsInLeague = (world.clubs.order || []).map(function(id){ return world.clubs.byId[id]; }).filter(function(entry){ return entry && entry.leagueKey === leagueKey; }).length || 18;
  var fixtures = ((((world||{}).calendar||{}).fixtures)||[]).filter(function(entry){ return entry.competition === 'league' && entry.roundType === 'league' && entry.leagueKey === leagueKey; });
  return clubsInLeague ? Math.round((fixtures.length * 2) / clubsInLeague) : 0;
}

function buildLeaguePlayerStatMap(world, leagueKey, seasonKey){
  var cacheKey = ['league-playerstats', leagueKey || '', seasonKey || 'current'].join('|');
  var cached = statisticsCacheGet(world, cacheKey);
  if (cached) return Object.assign({}, cached);
  var statsById = {};
  if (!world || !leagueKey) return statsById;
  var targetSeason = seasonKey === 'current' ? Number(((world||{}).meta||{}).seasonNumber || 1) : (seasonKey === 'all' ? null : Number(seasonKey));
  var sourceMatches = targetSeason == null ? playedMatches(world) : indexedMatchesForSeasonCompetition(world, targetSeason, 'league');
  sourceMatches.forEach(function(match){
    if (match.status !== 'played' || match.competition !== 'league' || match.roundType !== 'league' || match.leagueKey !== leagueKey) return;
    if (targetSeason != null && Number(match.season || 1) !== targetSeason) return;
    (match.playerStats || []).forEach(function(entry){
      if (!entry || !entry.playerId) return;
      var player = (((world||{}).players||{}).byId||{})[entry.playerId] || {};
      var clubId = entry.clubId || (entry.side === 'home' ? match.homeClubId : match.awayClubId);
      var bucket = statsById[entry.playerId] || (statsById[entry.playerId] = {
        playerId: entry.playerId,
        name: player.fullName || ('Spieler ' + entry.playerId),
        clubId: clubId,
        appearances: 0, goals: 0, assists: 0, scorers: 0, yellow: 0, yellowRed: 0, red: 0,
        ratingTotal: 0, ratingCount: 0, avgRating: null, cleanSheets: 0, goalsAgainst: 0, goalkeeper: String(player.mainPosition || '') === 'TW'
      });
      bucket.clubId = clubId;
      bucket.appearances += Number(entry.appearances || 0);
      bucket.goals += Number(entry.goals || 0);
      bucket.assists += Number(entry.assists || 0);
      bucket.scorers = bucket.goals + bucket.assists;
      bucket.yellow += Number(entry.yellow || 0);
      bucket.yellowRed += Number(entry.yellowRed || 0);
      bucket.red += Number(entry.red || 0);
      if (typeof entry.rating === 'number' && isFinite(entry.rating)) {
        bucket.ratingTotal += Number(entry.rating || 0);
        bucket.ratingCount += 1;
      }
      if (bucket.goalkeeper && Number(entry.appearances || 0) > 0) {
        var against = entry.side === 'home' ? Number(match.awayGoals || 0) : Number(match.homeGoals || 0);
        bucket.goalsAgainst += against;
        if (against === 0) bucket.cleanSheets += 1;
      }
    });
  });
  Object.keys(statsById).forEach(function(playerId){
    var bucket = statsById[playerId];
    bucket.avgRating = bucket.ratingCount ? round2(bucket.ratingTotal / bucket.ratingCount) : null;
  });
  statisticsCacheSet(world, cacheKey, Object.assign({}, statsById));
  return statsById;
}


