function buildFieberCupPlayerStatMap(world, seasonKey){
  var cacheKey = ['fieber-playerstats', seasonKey || 'current'].join('|');
  var cached = statisticsCacheGet(world, cacheKey);
  if (cached) return Object.assign({}, cached);
  var map = {};
  var targetSeason = seasonKey === 'current' || !seasonKey ? Number(((world||{}).meta||{}).seasonNumber || 1) : (seasonKey === 'all' ? null : Number(seasonKey));
  var sourceMatches = targetSeason == null ? playedMatches(world) : indexedMatchesForSeasonCompetition(world, targetSeason, 'fiebercup');
  sourceMatches.forEach(function(match){
    if (!match || match.status !== 'played' || match.competition !== 'fiebercup') return;
    // Die Fiebercup-Spielerstatistik im Statistikmenue beschreibt den Hauptwettbewerb.
    // Die Qualifikation ist eine vorgelagerte Ausscheidung und darf vor dem ersten Hauptfeldspiel keine Werte erzeugen.
    if (match.stage === 'qualification') return;
    if (targetSeason != null && Number(match.season || 1) !== targetSeason) return;
    (match.playerStats || []).forEach(function(stat){
      if (!stat || !stat.playerId) return;
      var appeared = Number(stat.appearances || 0) > 0 || Number(stat.minutesPlayed || 0) > 0;
      if (!appeared && !(Number(stat.goals||0) || Number(stat.assists||0) || typeof stat.rating === 'number')) return;
      var player = (((world||{}).players||{}).byId||{})[stat.playerId]; if (!player) return;
      var clubId = stat.clubId || player.clubId || (stat.side === 'home' ? match.homeClubId : match.awayClubId);
      var club = (((world||{}).clubs||{}).byId||{})[clubId] || {};
      if (!map[player.id]) map[player.id] = { playerId:player.id, name:player.fullName || player.name || '-', clubId:clubId, clubName:club.name || '-', appearances:0, minutes:0, goals:0, assists:0, scorers:0, yellow:0, yellowRed:0, red:0, ratingSum:0, ratingCount:0, avgRating:null, goalkeeper: player.mainPosition === 'TW', goalsAgainst:0, cleanSheets:0 };
      var row=map[player.id];
      row.clubId = clubId;
      if (appeared) row.appearances += 1;
      row.minutes += Number(stat.minutesPlayed||0);
      row.goals += Number(stat.goals||0); row.assists += Number(stat.assists||0); row.scorers = row.goals + row.assists;
      row.yellow += Number(stat.yellowCards||stat.yellow||0); row.yellowRed += Number(stat.yellowRedCards||stat.yellowRed||0); row.red += Number(stat.redCards||stat.red||0);
      if (typeof stat.rating === 'number' && isFinite(stat.rating)) { row.ratingSum += Number(stat.rating); row.ratingCount += 1; row.avgRating = row.ratingSum / row.ratingCount; }
      if (row.goalkeeper && appeared) {
        var side = stat.side || (((match.homeLineupIds||[]).indexOf(player.id)!==-1) ? 'home' : 'away');
        var ga = side === 'home' ? Number(match.awayGoals||0) : Number(match.homeGoals||0);
        row.goalsAgainst += ga; if (ga === 0) row.cleanSheets += 1;
      }
    });
  });
  statisticsCacheSet(world, cacheKey, Object.assign({}, map));
  return map;
}

