  var cards = topRows(function(a,b){ return Number(b.red||0)-Number(a.red||0) || Number(b.yellowRed||0)-Number(a.yellowRed||0) || Number(b.yellow||0)-Number(a.yellow||0); }, function(row){ return Number(row.yellow||0)+Number(row.yellowRed||0)+Number(row.red||0)>0; });
