    renderLeagueMiniStatsTable('Torjäger', goals, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'goals', label:'Tore', align:'align-center' }, { key:'appearances', label:'Sp.', align:'align-center' } ]) +
    renderLeagueMiniStatsTable('Vorlagengeber', assists, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'assists', label:'Vor.', align:'align-center' }, { key:'appearances', label:'Sp.', align:'align-center' } ]) +
    renderLeagueMiniStatsTable('Scorer', scorers, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'scorers', label:'Sc.', align:'align-center' }, { key:'goals', label:'Tore', align:'align-center' }, { key:'assists', label:'Vor.', align:'align-center' } ]) +
    renderLeagueMiniStatsTable('Notenbester', ratings, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'avgRatingDisplay', label:'Ø-Note', align:'align-center' }, { key:'appearances', label:'Sp.', align:'align-center' } ]) +
    renderLeagueMiniStatsTable('Strafen', cards, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'yellow', label:'Gelb', align:'align-center' }, { key:'yellowRed', label:'G/R', align:'align-center' }, { key:'red', label:'Rot', align:'align-center' } ]) +
    renderLeagueMiniStatsTable('Torhüter', keepers, [ { key:'position', label:'Pl.' }, { key:'name', label:'Spieler' }, { key:'appearances', label:'Sp.', align:'align-center' }, { key:'goalsAgainst', label:'GT', align:'align-center' }, { key:'cleanSheets', label:'Zu 0', align:'align-center' }, { key:'avgRatingDisplay', label:'Ø-Note', align:'align-center' } ]) + '</div>';
