function relegationEntriesForMatches(world, matches){
  var byKey = {};
  function add(entry){
    if (!entry || entry.roundType !== 'relegation' || !entry.tieId) return;
    var key = entry.fixtureId || entry.id || [entry.tieId, entry.leg, entry.homeClubId, entry.awayClubId].join('|');
    byKey[key] = entry;
  }
  (matches || []).forEach(function(match){
    if (!match || !match.tieId) return;
    relegationFixturesForTie(world, match.tieId).forEach(add);
    matchesForTie(world, match.tieId).forEach(add);
  });
  return Object.values(byKey).sort(function(a,b){ return String(a.countryName||'').localeCompare(String(b.countryName||''),'de') || Number(a.pairIndex||0)-Number(b.pairIndex||0) || Number(a.leg||0)-Number(b.leg||0); });
}

