function assistantCoachTypeData(profile){
  return (StaticData.coachTypes && StaticData.coachTypes[profile && profile.key]) || {};
}
function assistantFormationLabel(formationKey){
  var entry = formationLookup()[formationKey] || {};
  return entry.label || formationKey || '-';
}
function assistantUniqueList(items){
  var seen = {};
  return (items || []).filter(function(item){ if (!item || seen[item]) return false; seen[item] = true; return true; });
}
function assistantPlayerAvailable(player){
  if (!player) return false;
  var injured = playerIssueCount(player, ['injuryMatchesLeft','injuryWeeksLeft','injuryDaysLeft','injuryGamesLeft','injuryCount','injured']) > 0;
  var suspended = playerIssueCount(player, ['suspensionMatchesLeft','suspensionGamesLeft','suspensionCount','suspended']) > 0;
  return !injured && !suspended;
}
function assistantCoachStyleBonus(player, targetPosition, profile){
  if (!player || !profile) return 0;
  var group = positionGroupForPosition(targetPosition);
  var pos = targetPosition || '';
  var bonus = 0;
  if (profile.key === 'offensivdenker') {
    if (group === 'attack') bonus += 180;
    if (Number(player.form || 8) >= 8) bonus += 55;
  } else if (profile.key === 'defensivstratege') {
    if (group === 'defense' || pos === 'DM') bonus += 190;
    if (Number(player.fitness || 8) >= 8) bonus += 45;
  } else if (profile.key === 'fluegelfokus') {
    if (['LF','RF','LM','RM','LV','RV'].indexOf(pos) > -1) bonus += 210;
  } else if (profile.key === 'zentrumskontrolleur') {
    if (['DM','ZM','OM','ST','IV'].indexOf(pos) > -1) bonus += 150;
  } else {
    bonus += Number(player.fitness || 8) * 5 + Number(player.form || 8) * 5;
  }
  return bonus;
}
function assistantCandidateScoreForSlot(player, formationKey, slotId, profile){
  var ctx = playerEffectiveContextForSlot(player, formationKey, slotId);
  return formationSlotAssignmentScore(player, formationKey, slotId) + assistantCoachStyleBonus(player, ctx.targetPosition, profile);
}

function assistantBenchGroupForPlayer(player){
  if (!player) return 'reserve';
  if (player.mainPosition === 'TW') return 'keeper';
  var group = positionGroupForPosition(player.mainPosition);
  if (group === 'attack') return 'attack';
  if (group === 'midfield') return 'midfield';
  if (group === 'defense' || player.mainPosition === 'DM') return 'defense';
  return 'reserve';
}
function assistantBenchScoreForPlayer(player, profile){
  if (!player) return 0;
  var base = Number(calculatePlayerCurrentOverallAdvanced(player) || player.overall || 0) * 10 + Number(player.fitness || 8) * 2 + Number(player.form || 8) * 2;
  var group = assistantBenchGroupForPlayer(player);
  if (profile && profile.key === 'offensivdenker' && group === 'attack') base += 90;
  if (profile && profile.key === 'defensivstratege' && group === 'defense') base += 90;
  if (profile && profile.key === 'fluegelfokus' && ['LF','RF','LM','RM','LV','RV'].indexOf(player.mainPosition) > -1) base += 80;
  if (profile && profile.key === 'zentrumskontrolleur' && ['DM','ZM','OM','ST','IV'].indexOf(player.mainPosition) > -1) base += 60;
  return base;
}
function assistantOrderBenchCandidates(restIds, world, profile){
  var remaining = (restIds || []).slice();
  var bench = [];
  function takeBestByGroup(groupName){
    var candidates = remaining.filter(function(playerId){ return assistantBenchGroupForPlayer(world.players.byId[playerId]) === groupName; });
    if (!candidates.length || bench.length >= LINEUP_BENCH_SLOTS.length) return;
    candidates.sort(function(a,b){ return assistantBenchScoreForPlayer(world.players.byId[b], profile) - assistantBenchScoreForPlayer(world.players.byId[a], profile); });
    var chosen = candidates[0];
    bench.push(chosen);
    remaining = remaining.filter(function(playerId){ return playerId !== chosen; });
  }
  ['keeper','defense','midfield','attack'].forEach(takeBestByGroup);
  remaining.sort(function(a,b){ return assistantBenchScoreForPlayer(world.players.byId[b], profile) - assistantBenchScoreForPlayer(world.players.byId[a], profile); });
  remaining.forEach(function(playerId){ if (bench.length < LINEUP_BENCH_SLOTS.length) bench.push(playerId); });
  return bench.concat(remaining.filter(function(playerId){ return bench.indexOf(playerId) === -1; }));
}
function assistantBuildPlacementForFormation(squad, world, formationKey, profile, competition){
  var placement = {};
  var allIds = (squad.playerIds || []).slice().filter(function(playerId){ return world.players.byId[playerId]; });
  var availableIds = allIds.filter(function(playerId){ return assistantPlayerAvailable(world.players.byId[playerId], competition || 'league'); });
  if (availableIds.length < 11) availableIds = allIds.slice();
  var keeperIds = availableIds.filter(function(playerId){ var player = world.players.byId[playerId]; return player && player.mainPosition === 'TW'; });
  if (!keeperIds.length) keeperIds = allIds.filter(function(playerId){ var player = world.players.byId[playerId]; return player && player.mainPosition === 'TW'; });
  var keeperId = keeperIds.sort(function(a,b){
    var pa = world.players.byId[a], pb = world.players.byId[b];
    var sa = Number(calculatePlayerCurrentOverallAdvanced(pa) || pa.overall || 0) + Number(pa.fitness || 8) + Number(pa.form || 8);
    var sb = Number(calculatePlayerCurrentOverallAdvanced(pb) || pb.overall || 0) + Number(pb.fitness || 8) + Number(pb.form || 8);
    return sb - sa;
  })[0] || null;
  if (keeperId) placement[keeperId] = { location:'field', slot:'goal_basic_z' };
  var remaining = availableIds.filter(function(playerId){ return playerId !== keeperId && world.players.byId[playerId] && world.players.byId[playerId].mainPosition !== 'TW'; });
  var slots = orderedFormationSlots(formationKey).slice();
  slots.forEach(function(slotId){
    if (!remaining.length) return;
    var best = remaining.map(function(playerId){ return { playerId:playerId, score:assistantCandidateScoreForSlot(world.players.byId[playerId], formationKey, slotId, profile) }; }).sort(function(a,b){ return b.score - a.score; })[0];
    if (!best) return;
    placement[best.playerId] = { location:'field', slot:slotId };
    remaining = remaining.filter(function(playerId){ return playerId !== best.playerId; });
  });
  var selected = {};
  Object.keys(placement).forEach(function(playerId){ selected[playerId] = true; });
  var rest = assistantOrderBenchCandidates(allIds.filter(function(playerId){ return !selected[playerId]; }), world, profile);
  rest.forEach(function(playerId, index){
    if (index < LINEUP_BENCH_SLOTS.length) placement[playerId] = { location:'bench', slot:LINEUP_BENCH_SLOTS[index] };
    else placement[playerId] = { location:'reserve', slot:null };
  });
  return placement;
}
function assistantMetricsForPlacement(formationKey, placement, tactics, world){
  var fieldIds = Object.keys(placement || {}).filter(function(playerId){ return placement[playerId] && placement[playerId].location === 'field'; });
  var values = [];
  var fitValues = [];
  var formValues = [];
  var attackValues = [];
  var defenseValues = [];
  var midfieldCount = 0, attackCount = 0, defenseCount = 0, totalMalus = 0;
  fieldIds.forEach(function(playerId){
    var player = world.players.byId[playerId];
    if (!player) return;
    var info = placement[playerId] || {};
    if (info.slot === 'goal_basic_z' || player.mainPosition === 'TW') {
      var keeperOverall = Number(calculatePlayerCurrentOverallAdvanced(player) || player.overall || 0);
      values.push(keeperOverall);
      defenseValues.push(keeperOverall);
      fitValues.push(Number(levelTo10(player.fitness || 8)));
      formValues.push(Number(levelTo10(player.form || 8)));
      return;
    }
    var ctx = playerEffectiveContextForSlot(player, formationKey, info.slot);
    var effective = Number(ctx.effectiveOverall || calculatePlayerCurrentOverallAdvanced(player) || player.overall || 0);
    values.push(effective);
    fitValues.push(Number(levelTo10(player.fitness || 8)));
    formValues.push(Number(levelTo10(player.form || 8)));
    totalMalus += Number((ctx.penalty || {}).malus || 0);
    var group = positionGroupForPosition(ctx.targetPosition);
    if (group === 'attack') { attackCount += 1; attackValues.push(effective); }
    else if (group === 'defense') { defenseCount += 1; defenseValues.push(effective); }
    else if (group === 'midfield') { midfieldCount += 1; }
  });
  function avg(arr){ return arr.length ? round2(arr.reduce(function(sum, value){ return sum + Number(value || 0); }, 0) / arr.length) : 0; }
  var penalty = 0;
  if (fieldIds.length !== 11) penalty += Math.abs(11 - fieldIds.length) * 9;
  if (defenseCount < 3) penalty += 18;
  if (defenseCount > 6) penalty += 8;
  if (midfieldCount < 2) penalty += 18;
  if (attackCount < 1) penalty += 12;
  if (attackCount > 4) penalty += 10;
  penalty += Math.min(22, totalMalus / 4);
  if (tactics && tactics.pressing === 'high' && avg(fitValues) <= 7) penalty += 6;
  return {
    strength: avg(values),
    fitness: avg(fitValues),
    form: avg(formValues),
    structure: Math.max(20, Math.round(100 - penalty)),
    attack: avg(attackValues),
    defense: avg(defenseValues)
  };
}
function assistantTacticsForCoach(profile, currentTactics){
  var next = Object.assign({}, LINEUP_TACTIC_DEFAULTS, currentTactics || {});
  next = Object.keys(LINEUP_TACTIC_DEFAULTS).reduce(function(obj, key){ obj[key] = tacticValueNumber(key, next[key]); return obj; }, {});
  var base = baseCoachTacticPlan(profile && profile.key ? profile.key : 'pragmatiker');
  Object.keys(base).forEach(function(key){ next[key] = base[key]; });
  return next;
}
function assistantLineupProposalForClub(club, squad, world){
  ensureLineupMaskState(club, squad, world);
  var profile = lineupTrainerProfile(club);
  var assistantCompetition = assistantCompetitionForClub(world, club);
  var coachData = assistantCoachTypeData(profile);
  var currentFormationKey = currentSquadFormationKey(world, club);
  var currentPlacement = (squad.lineupMaskState && squad.lineupMaskState.playerPlacementById) || {};
  var currentTactics = Object.assign({}, ensureSquadTactics(squad));
  var targetTactics = assistantTacticsForCoach(profile, currentTactics);
  var candidates = assistantUniqueList([coachData.favoriteFormation1, coachData.favoriteFormation2, coachData.favoriteFormation3, coachData.toleratedFormation1, coachData.toleratedFormation2, currentFormationKey]).filter(function(key){ return formationLookup()[key]; });
  if (!candidates.length) candidates = [currentFormationKey];
  var evaluated = candidates.map(function(key){
    var placement = assistantBuildPlacementForFormation(squad, world, key, profile, assistantCompetition);
    var metrics = assistantMetricsForPlacement(key, placement, targetTactics, world);
    var styleScore = metrics.strength + metrics.structure * 0.55 + metrics.form * 1.6 + metrics.fitness * 1.2;
    if (profile.key === 'offensivdenker') styleScore += metrics.attack * 0.42 - metrics.defense * 0.08;
    else if (profile.key === 'defensivstratege') styleScore += metrics.defense * 0.45 + metrics.structure * 0.25;
    else if (profile.key === 'fluegelfokus') styleScore += key.indexOf('4_3_3') > -1 || key.indexOf('3_4_3') > -1 ? 12 : 0;
    else if (profile.key === 'zentrumskontrolleur') styleScore += key.indexOf('4_1') > -1 || key.indexOf('4_2_3_1') > -1 ? 10 : 0;
    else styleScore += Math.min(metrics.structure, metrics.strength) * 0.25;
    return { formationKey:key, placement:placement, metrics:metrics, styleScore:styleScore };
  }).sort(function(a,b){ return b.styleScore - a.styleScore; });
  var best = evaluated[0] || { formationKey:currentFormationKey, placement:currentPlacement, metrics:assistantMetricsForPlacement(currentFormationKey, currentPlacement, currentTactics, world), styleScore:0 };
  var currentMetrics = assistantMetricsForPlacement(currentFormationKey, currentPlacement, currentTactics, world);
  var currentField = Object.keys(currentPlacement).filter(function(playerId){ return currentPlacement[playerId] && currentPlacement[playerId].location === 'field'; });
  var proposedField = Object.keys(best.placement).filter(function(playerId){ return best.placement[playerId] && best.placement[playerId].location === 'field'; });
  var currentBench = Object.keys(currentPlacement).filter(function(playerId){ return currentPlacement[playerId] && currentPlacement[playerId].location === 'bench'; });
  var proposedBench = Object.keys(best.placement).filter(function(playerId){ return best.placement[playerId] && best.placement[playerId].location === 'bench'; });
  function difference(source, target){ return source.filter(function(id){ return target.indexOf(id) === -1; }); }
  return {
    profile:profile,
    currentFormationKey:currentFormationKey,
    targetFormationKey:best.formationKey,
    currentTactics:currentTactics,
    targetTactics:targetTactics,
    currentMetrics:currentMetrics,
    targetMetrics:best.metrics,
    placement:best.placement,
    playersIn:difference(proposedField, currentField),
    playersOut:difference(currentField, proposedField),
    benchIn:difference(proposedBench, currentBench),
    benchOut:difference(currentBench, proposedBench)
  };
}
function assistantMetricRow(label, currentValue, nextValue){
  var diff = round2(Number(nextValue || 0) - Number(currentValue || 0));
  var cls = diff > 0 ? ' is-up' : (diff < 0 ? ' is-down' : '');
  var sign = diff > 0 ? '+' : '';
  return '<div class="lineup-trainerstaff-proposal-metric' + cls + '"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(currentValue) + ' &rarr; ' + escapeHtml(nextValue) + '</strong><em>' + escapeHtml(sign + diff) + '</em></div>';
}
function assistantTacticLabel(kind, tactics){
  return lineupTacticOption(kind, tactics && tactics[kind]).label;
}
function assistantPlayerShortName(playerId){
  var player = AppState.world && AppState.world.players && AppState.world.players.byId ? AppState.world.players.byId[playerId] : null;
  return player ? (player.lastName || player.fullName || playerId) : playerId;
}
function renderAssistantLineupProposalModalBody(club, squad){
  var proposal = assistantLineupProposalForClub(club, squad, AppState.world);
  var tacticChanges = ['mentality','attackStyle','attackSide','pressing','buildUp','defensiveLine','transitionAttack','transitionDefense'].map(function(kind){
    var current = assistantTacticLabel(kind, proposal.currentTactics);
    var next = assistantTacticLabel(kind, proposal.targetTactics);
    var title = (LINEUP_TACTIC_DEFS[kind] || {}).title || kind;
    return '<div><span>' + escapeHtml(title) + '</span><strong>' + escapeHtml(current) + ' &rarr; ' + escapeHtml(next) + '</strong></div>';
  }).join('');
  var maxRows = Math.max(proposal.playersIn.length, proposal.playersOut.length, 1);
  var playerRows = [];
  for (var i = 0; i < maxRows && i < 5; i += 1) {
    playerRows.push('<div class="lineup-trainerstaff-proposal-player-row"><span>' + escapeHtml(proposal.playersOut[i] ? assistantPlayerShortName(proposal.playersOut[i]) : '-') + '</span><em>&rarr;</em><strong>' + escapeHtml(proposal.playersIn[i] ? assistantPlayerShortName(proposal.playersIn[i]) : '-') + '</strong></div>');
  }
  if (!proposal.playersIn.length && !proposal.playersOut.length) playerRows = ['<div class="lineup-trainerstaff-proposal-player-row"><span>Startelf</span><em>&rarr;</em><strong>keine Wechsel im Vorschlag</strong></div>'];
  var benchMaxRows = Math.max((proposal.benchIn || []).length, (proposal.benchOut || []).length, 1);
  var benchRows = [];
  for (var bi = 0; bi < benchMaxRows && bi < 5; bi += 1) {
    benchRows.push('<div class="lineup-trainerstaff-proposal-player-row"><span>' + escapeHtml(proposal.benchOut && proposal.benchOut[bi] ? assistantPlayerShortName(proposal.benchOut[bi]) : '-') + '</span><em>&rarr;</em><strong>' + escapeHtml(proposal.benchIn && proposal.benchIn[bi] ? assistantPlayerShortName(proposal.benchIn[bi]) : '-') + '</strong></div>');
  }
  if (!(proposal.benchIn || []).length && !(proposal.benchOut || []).length) benchRows = ['<div class="lineup-trainerstaff-proposal-player-row"><span>Bank</span><em>&rarr;</em><strong>keine Bankwechsel im Vorschlag</strong></div>'];
  return '<div class="lineup-trainerstaff-proposal-modal">' +
    '<p><strong>' + escapeHtml(proposal.profile.label) + ':</strong> Dieser Vorschlag folgt dem Trainertyp und kann besser, schlechter oder nur anders sein. Er wird erst nach deiner Bestätigung übernommen.</p>' +
    '<div class="lineup-trainerstaff-proposal-scroll">' +
    '<section class="lineup-trainerstaff-proposal-block"><h3>Formation</h3><div class="lineup-trainerstaff-proposal-formation"><strong>' + escapeHtml(assistantFormationLabel(proposal.currentFormationKey)) + '</strong><em>&rarr;</em><strong>' + escapeHtml(assistantFormationLabel(proposal.targetFormationKey)) + '</strong></div></section>' +
    '<section class="lineup-trainerstaff-proposal-block"><h3>Startelf</h3><div class="lineup-trainerstaff-proposal-players">' + playerRows.join('') + '</div></section>' +
    '<section class="lineup-trainerstaff-proposal-block"><h3>Bank</h3><div class="lineup-trainerstaff-proposal-players">' + benchRows.join('') + '</div></section>' +
    '<section class="lineup-trainerstaff-proposal-block"><h3>Taktik</h3><div class="lineup-trainerstaff-proposal-tactics">' + tacticChanges + '</div></section>' +
    '<section class="lineup-trainerstaff-proposal-block"><h3>Auswirkung</h3><div class="lineup-trainerstaff-proposal-metrics">' +
      assistantMetricRow('Staerke', proposal.currentMetrics.strength, proposal.targetMetrics.strength) +
      assistantMetricRow('Form', proposal.currentMetrics.form, proposal.targetMetrics.form) +
      assistantMetricRow('Fitness', proposal.currentMetrics.fitness, proposal.targetMetrics.fitness) +
      assistantMetricRow('Struktur', proposal.currentMetrics.structure, proposal.targetMetrics.structure) +
      assistantMetricRow('Offensive', proposal.currentMetrics.attack, proposal.targetMetrics.attack) +
      assistantMetricRow('Defensive', proposal.currentMetrics.defense, proposal.targetMetrics.defense) +
    '</div></section>' +
    '</div>' +
    '<div class="calendar-popup-actions"><button class="ghost-btn" type="button" data-action="calendar-sim-cancel">Abbrechen</button><button class="primary-btn" type="button" data-action="lineup-assistant-apply-lineup-proposal">Vorschlag übernehmen</button></div>' +
  '</div>';
}
function applyAssistantLineupProposal(club, squad, world){
  var proposal = assistantLineupProposalForClub(club, squad, world);
  squad.tactics = Object.assign({}, proposal.targetTactics);
  squad.lineupMaskState = { formationKey:proposal.targetFormationKey, playerPlacementById:proposal.placement, sort:{ key:'usage', dir:'asc' } };
  syncSquadFromLineupMaskState(club, squad, world);
}
function assistantAverage(items, fn){
  var values = (items || []).map(fn).filter(function(value){ return isFinite(value); });
  if (!values.length) return 0;
  return round2(values.reduce(function(sum, value){ return sum + value; }, 0) / values.length);
}
function assistantSlotSide(slotId){
  var coord = slotGridCoordinate(slotId);
  if (coord.col <= 1) return 'left';
  if (coord.col >= 3) return 'right';
  return 'center';
}
function generateLineupAssistantHints(club, squad, world){
  var hints = [];
  function add(level, title, text){ hints.push({ level:level, title:title, text:text }); }
  if (!world || !club || !squad) return [{ level:'warn', title:'Keine Analyse möglich', text:'Es ist kein aktiver Verein oder Kader verfügbar.' }];
  ensureLineupMaskState(club, squad, world);
  var tactics = ensureSquadTactics(squad);
  var formationStatus = lineupFormationStatus(club, squad);
  var formationKey = currentSquadFormationKey(AppState.world, club);
  var placement = squad.lineupMaskState && squad.lineupMaskState.playerPlacementById ? squad.lineupMaskState.playerPlacementById : {};
  var fieldIds = Object.keys(placement).filter(function(playerId){ return placement[playerId] && placement[playerId].location === 'field'; });
  var benchIds = Object.keys(placement).filter(function(playerId){ return placement[playerId] && placement[playerId].location === 'bench'; });
  var fieldPlayers = fieldIds.map(function(playerId){ return world.players.byId[playerId]; }).filter(Boolean);
  var benchPlayers = benchIds.map(function(playerId){ return world.players.byId[playerId]; }).filter(Boolean);
  var outfieldPlayers = fieldPlayers.filter(function(player){ return player.mainPosition !== 'TW'; });
  var keeperSlotId = lineupPlayerAt(squad, 'field', 'goal_basic_z');
  var keeper = keeperSlotId && world.players.byId ? world.players.byId[keeperSlotId] : null;

  if (fieldIds.length === 11) add('good', 'Startelf vollständig', 'Es stehen 11 Spieler in der Startelf.');
  else add('warn', 'Startelf nicht vollständig', 'Aktuell stehen ' + fieldIds.length + '/11 Spieler in der Startelf.');
  if (!keeper) add('warn', 'Torwart fehlt', 'Im Torwartslot steht kein Spieler. Der Slot muss vor Spielstart besetzt werden.');
  else if (keeper.mainPosition !== 'TW') add('warn', 'Not-Torwart im Tor', (keeper.lastName || keeper.fullName || 'Ein Feldspieler') + ' steht im Tor. Das ist erlaubt, fuehrt aber zu einem deutlichen Torwart-Malus.');
  else add('good', 'Torwart besetzt', (keeper.lastName || keeper.fullName || 'Der Torwart') + ' steht im Tor.');

  var assistantCompetition = assistantCompetitionForClub(world, club);
  var unavailable = fieldPlayers.filter(function(player){ return kf021PlayerInjurySlotsLeft(player) > 0 || playerSuspensionApplies(player, assistantCompetition); });
  if (unavailable.length) add('warn', 'Nicht verfuegbare Spieler', unavailable.length + ' Startelfspieler sind verletzt oder gesperrt.');

  var groupCounts = { defense:0, midfield:0, attack:0, goal:0 };
  fieldPlayers.forEach(function(player){ var group = positionGroupForPosition(player.mainPosition); if (groupCounts[group] != null) groupCounts[group] += 1; });
  if (groupCounts.attack >= 6) add('warn', 'Extrem offensive Besetzung', groupCounts.attack + ' gelernte Offensivspieler in der Startelf koennen Mittelfeldkontrolle und Restverteidigung stark schwaechen.');
  if (groupCounts.defense >= 7) add('warn', 'Extrem defensive Besetzung', groupCounts.defense + ' gelernte Defensivspieler sorgen für Stabilitaet, aber kaum Entlastung nach vorne.');
  if (groupCounts.midfield <= 1) add('warn', 'Zentrum unterbesetzt', 'Mit nur ' + groupCounts.midfield + ' gelernten Mittelfeldspielern kann der Spielaufbau instabil werden.');
  if (groupCounts.defense <= 2) add('warn', 'Absicherung riskant', 'Die Startelf hat nur ' + groupCounts.defense + ' gelernte Defensivspieler. Konter und Fluegelduelle koennen kritisch werden.');
  if (groupCounts.attack === 0) add('warn', 'Keine offensive Zielposition', 'Ohne gelernten Offensivspieler fehlt Entlastung und Abschlussqualitaet.');
  if (!formationStatus.exact) add('info', 'Formation manuell angepasst', 'Die aktuelle Feldbesetzung weicht von der gewaehlten Formation ab. Die Matchengine sollte diese Struktur spaeter separat bewerten.');

  var outOfPosition = fieldIds.filter(function(playerId){
    var player = world.players.byId[playerId];
    if (!player || player.mainPosition === 'TW') return false;
    var info = lineupPlacementForPlayer(squad, playerId);
    if (!info || !info.slot) return false;
    var ctx = playerEffectiveContextForSlot(player, formationKey, info.slot);
    return Number((ctx.penalty || {}).malus || 0) >= 8;
  });
  if (outOfPosition.length >= 3) add('warn', 'Viele positionsfremde Rollen', outOfPosition.length + ' Feldspieler haben deutliche Positionsmali. Das kann Ordnung und Feldduelle schwaechen.');
  else if (outOfPosition.length > 0) add('info', 'Positionsmali beachten', outOfPosition.length + ' Feldspieler spielen deutlich ausserhalb ihrer Idealrolle.');

  var avgFit = assistantAverage(fieldPlayers, function(player){ return Number(levelTo10(player.fitness || 8)); });
  var lowFitness = fieldPlayers.filter(function(player){ return Number(levelTo10(player.fitness || 8)) <= 6; });
  if (lowFitness.length >= 3) add('warn', 'Fitnessrisiko', lowFitness.length + ' Startelfspieler liegen bei Fitness 6 oder niedriger. Die Schlussphase kann problematisch werden.');
  else if (lowFitness.length > 0) add('info', 'Einzelne Fitnessrisiken', lowFitness.length + ' Startelfspieler haben niedrige Fitness.');
  if (tacticNumber(tactics, 'pressing') >= 2 && avgFit > 0 && avgFit <= 7) add('warn', 'Hohes Pressing bei knapper Fitness', 'Hohes Pressing mit Ø Fitness ' + avgFit + ' kann zu spaeter Muedigkeit, Fouls und Karten fuehren.');
  if (tacticNumber(tactics, 'mentality') >= 1 && groupCounts.defense <= 3) add('warn', 'Offensive Ausrichtung mit wenig Absicherung', 'Die gewaehlte Grundausrichtung erhoeht das Konterrisiko bei dieser defensiven Besetzung.');

  var sideData = { left:{ total:0, count:0 }, right:{ total:0, count:0 }, center:{ total:0, count:0 } };
  fieldIds.forEach(function(playerId){
    var player = world.players.byId[playerId];
    if (!player || player.mainPosition === 'TW') return;
    var info = lineupPlacementForPlayer(squad, playerId);
    if (!info || !info.slot) return;
    var side = assistantSlotSide(info.slot);
    var ctx = playerEffectiveContextForSlot(player, formationKey, info.slot);
    sideData[side].total += Number(ctx.effectiveOverall || 0);
    sideData[side].count += 1;
  });
  function sideAvg(side){ return sideData[side].count ? sideData[side].total / sideData[side].count : 0; }
  var leftAvg = sideAvg('left'), rightAvg = sideAvg('right'), centerAvg = sideAvg('center');
  if (tacticNumber(tactics, 'attackSide') >= 1) {
    if (rightAvg + 4 < leftAvg) add('warn', 'Rechtsfokus fraglich', 'Die rechte Seite wirkt schwaecher als links. Der Schwerpunkt koennte verpuffen.');
    else add('good', 'Rechtsfokus nachvollziehbar', 'Die rechte Seite wird bewusst eingebunden und ist strukturell ausreichend besetzt.');
  }
  if (tacticNumber(tactics, 'attackSide') <= -1) {
    if (leftAvg + 4 < rightAvg) add('warn', 'Linksfokus fraglich', 'Die linke Seite wirkt schwaecher als rechts. Der Schwerpunkt koennte verpuffen.');
    else add('good', 'Linksfokus nachvollziehbar', 'Die linke Seite wird bewusst eingebunden und ist strukturell ausreichend besetzt.');
  }
  if (tacticNumber(tactics, 'attackStyle') <= -1) {
    if (centerAvg + 4 < Math.max(leftAvg, rightAvg)) add('warn', 'Zentrumsfokus riskant', 'Das Zentrum wirkt nicht staerker als die Außenbahnen. Gegen kompakte Gegner kann es eng werden.');
    else add('good', 'Zentrumsfokus nachvollziehbar', 'Die zentrale Besetzung passt zum Spiel durch die Mitte.');
  }
  if (tacticNumber(tactics, 'attackStyle') >= 1) {
    if (sideData.left.count + sideData.right.count < 4) add('warn', 'Fluegelfokus ohne Breite', 'Fuer konsequentes Fluegelspiel sind die Außenbahnen knapp besetzt.');
    else add('good', 'Fluegelfokus passt zur Breite', 'Beide Außenbahnen sind ausreichend besetzt.');
  }
  generateTacticCombinationHints(tactics, club, squad).forEach(function(hint){ if (hint.level !== 'good') add(hint.level, hint.title, hint.text); });

  var chemistry = calculateTeamChemistry(world, club.id, null);
  (chemistry.hints || []).slice(0, 3).forEach(function(hint){ add(hint.level, hint.title, hint.text); });
  var benchDefense = benchPlayers.filter(function(player){ return positionGroupForPosition(player.mainPosition) === 'defense' || player.mainPosition === 'DM'; }).length;
  var benchAttack = benchPlayers.filter(function(player){ return positionGroupForPosition(player.mainPosition) === 'attack'; }).length;
  var benchKeeper = benchPlayers.some(function(player){ return player.mainPosition === 'TW'; });
  if (benchIds.length < 5) add('warn', 'Bank knapp besetzt', 'Auf der Bank stehen nur ' + benchIds.length + ' Spieler. Wechseloptionen sind begrenzt.');
  if (!benchKeeper) add('info', 'Kein Torwart auf der Bank', 'Bei einer Torwartverletzung waere nur eine Notloesung verfuegbar.');
  if (benchDefense === 0) add('info', 'Keine defensive Bankoption', 'Bei Fuehrung oder Verletzung fehlt ein klarer defensiver Ersatz.');
  if (benchAttack === 0) add('info', 'Keine offensive Bankoption', 'Bei Rueckstand fehlt ein klarer offensiver Impuls von der Bank.');

  if (!hints.length) add('good', 'Keine Auffaelligkeiten', 'Aufstellung, Taktik und Kaderzustand wirken für den naechsten Einsatz stabil.');
  return hints.slice(0, 8);
}
function renderLineupAssistantHints(club, squad){
  return generateLineupAssistantHints(club, squad, AppState.world).map(function(hint){
    return '<div class="lineup-assistant-hint is-' + escapeHtml(hint.level) + '"><strong>' + escapeHtml(hint.title) + '</strong><span>' + escapeHtml(hint.text) + '</span></div>';
  }).join('');
}
