function playerContractTerminationModalBody(world, playerId){
  world = world || AppState.world;
  var player = world && world.players && world.players.byId ? world.players.byId[playerId] : null;
  if (!player) return '<div class="notice">Spieler nicht gefunden.</div>';
  var club = playerClubById(player) || activeClub();
  var squad = club && world.squads ? (world.squads[club.id] || { playerIds:[] }) : { playerIds:[] };
  var data = playerContractData(world, player, club, squad);
  var estimate = playerContractTerminationEstimate(world, player, data);
  var remainingBaseSalary = roundContractAmount(Math.max(0, Number(data.baseSalary || 0) * Math.max(0, Number(data.remainingYears || 0))));
  var suggestedCompensation = estimate.likelyFree ? 0 : contractRoundMoney(Math.min(remainingBaseSalary, estimate.estimatedPenalty * 0.75), 1000);
  function stat(label, value, note){ return '<div class="contract-dialog-stat"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(value) + '</strong>' + (note ? '<em>' + escapeHtml(note) + '</em>' : '') + '</div>'; }
  function field(label, html){ return '<label><span>' + escapeHtml(label) + '</span>' + html + '</label>'; }
  var playerScore = estimate.likelyFree ? 72 : clampNumber(Math.round(36 + (suggestedCompensation / Math.max(0.01, remainingBaseSalary || estimate.estimatedPenalty || 1)) * 52 + (55 - playerMorale100(player)) * .18), 0, 100);
  var boardScore = clampNumber(Math.round(82 - (suggestedCompensation / Math.max(0.01, remainingBaseSalary || 1)) * 58), 0, 100);
  var assessment = { playerScore:playerScore, boardScore:boardScore, playerLabel: playerScore >= 70 ? 'Zustimmung realistisch' : playerScore >= 45 ? 'Entschädigung verhandelbar' : 'Ablehnung wahrscheinlich', boardLabel: boardScore >= 70 ? 'vertretbar' : boardScore >= 45 ? 'angespannt' : 'zu teuer', expectedBonus:suggestedCompensation, seasonCost:remainingBaseSalary };
  var currentStats = [
    stat('Restlaufzeit', String(data.remainingYears) + ' Saison(en)', data.validUntilLabel),
    stat('Rolle', data.roleLabel, 'Vertragszusage'),
    stat('Einsatz', assignedPositionForPlayer(club, squad, player.id), 'aktuelle Situation'),
    stat('Grundgehalt', formatContractMoneyFull(data.baseSalary), 'pro Saison'),
    stat('Obergrenze', formatContractMoneyFull(remainingBaseSalary), 'max. Grundgehalt bis Vertragsende'),
    stat('Orientierung', formatContractMoneyFull(estimate.estimatedPenalty), estimate.label)
  ].join('');
  return '<div class="player-contract-dialog contract-termination-modal" data-player-id="' + escapeHtml(player.id) + '">' +
    '<div class="contract-dialog-top contract-dialog-top-two">' +
      '<div class="contract-dialog-identity contract-dialog-playerblock"><span class="contract-dialog-kicker">Auflösung verhandeln</span><h3>' + escapeHtml(player.fullName || '-') + '</h3><p>' + escapeHtml((club && club.name) || '-') + ' · ' + escapeHtml(player.age || '-') + ' Jahre · ' + escapeHtml(player.mainPosition || '-') + '</p>' + contractPlayerOverallPanel(player, club, squad) + '</div>' +
      '<div class="contract-dialog-current contract-dialog-current-old"><h4>Aktueller Vertrag</h4>' + currentStats + '</div>' +
    '</div>' +
    '<div class="contract-offer-layout contract-termination-layout">' +
      '<section class="contract-new-offer"><h4>Auflösungsangebot</h4><div class="contract-offer-subgrid contract-termination-options">' +
        '<div class="contract-offer-block"><h5>Optionen</h5>' +
          field('Zeitpunkt','<select data-contract-field="terminationTime"><option value="now">sofort</option><option value="season_end">Saisonende</option></select>') +
          field('Entschädigung', contractMoneyRangeField('terminationCompensation', suggestedCompensation, 0, Math.max(remainingBaseSalary, 0.001), 1000, '0 € bis maximal Grundgehalt bis Vertragsende')) +
        '</div>' +
      '</div></section>' +
      '<aside class="contract-offer-summary"><div class="contract-summary-stack"><h4>Zusammenfassung</h4>' +
        renderContractAssessmentBars(assessment, 'termination') +
        '<div class="contract-diff-grid">' +
          contractSummaryCard('Angebotene Entschädigung', formatContractMoneyFull(suggestedCompensation), 'Reglerwert', '').replace('<strong>', '<strong data-contract-preview="termination-compensation">') +
          contractSummaryCard('Vorstandsobergrenze', formatContractMoneyFull(remainingBaseSalary), 'Grundgehalt bis Vertragsende', '') +
          contractSummaryCard('Ohne Entschädigung', estimate.likelyFree ? 'möglich' : 'unwahrscheinlich', 'abhängig von Moral und Rolle', '') +
          contractSummaryCard('Ersparnis/Jahr', formatContractMoneyFull(data.expectedSeasonCost), 'bei sofortiger Auflösung', '') +
        '</div></div></aside>' +
    '</div>' +
    '<div class="modal-actions sponsor-modal-actions contract-dialog-actions"><button class="ghost-btn" type="button" data-action="close-modal">Abbrechen</button><button class="primary-btn" type="button" disabled title="Die finale Auflösungslogik folgt im Vertragslogik-Block.">Auflösung anbieten</button></div>' +
  '</div>';
}
