function activeScoutingOrders(world, clubId){var data=ensureClubScoutingPlanning(world,clubId);return data?data.scouting.orders.filter(function(order){return order&&order.status==='active';}).sort(function(a,b){return a.slotIndex-b.slotIndex;}):[];}
