  if(Number.isFinite(focus.ageMin)&&Number.isFinite(focus.ageMax)&&focus.ageMin>focus.ageMax){var swap=focus.ageMin;focus.ageMin=focus.ageMax;focus.ageMax=swap;}
  var targets=scoutingTaskTargetPlayers(world,{targetType:targetType,targetId:targetId,scoutingFocus:focus});
  if(targetType==='player'&&!targets.length)return {ok:false,message:'Der ausgewählte Spieler wurde nicht gefunden.'};
  if(targetType==='club'&&!((((world||{}).clubs||{}).byId||{})[targetId]))return {ok:false,message:'Der ausgewählte Verein wurde nicht gefunden.'};
  if(targetType==='league'&&!((((world||{}).leagues||{}).byKey||{})[targetId]))return {ok:false,message:'Die ausgewählte Liga wurde nicht gefunden.'};
