  if(requestedSlot<0){for(var i=0;i<capacity;i++){if(!scoutingOrderAtSlot(world,clubId,i)){requestedSlot=i;break;}}}
  if(requestedSlot<0||requestedSlot>=capacity||requestedSlot>=limit)return {ok:false,message:'Es läuft bereits eine Scoutingaufgabe auf allen verfügbaren Plätzen.'};
