  if(duplicate)return {ok:false,message:'Dieses Ziel wird bereits aktiv gescoutet.'};
  var durationMode=options.durationMode==='continuous'?'continuous':'fixed';
  var duration=Math.max(rules.fixedDurationMin,Math.min(rules.fixedDurationMax,Number(durationSlots||8)));
  if(targetType==='player'&&durationMode==='continuous'&&effectivePlayerReliability(world,targets[0],clubId)>=10)return {ok:false,message:'Dieser Spieler ist bereits mit 10/10 Verlässlichkeit vollständig bekannt.'};
  if(occupied)completeScoutingOrder(world,clubId,occupied,'replaced','');
