function removePlayerFromSquadCollections(squad, playerId){
  if (!squad) return;
  ['playerIds','lineup','bench','reserve'].forEach(function(key){ squad[key] = (squad[key] || []).filter(function(id){ return id !== playerId; }); });
  if (squad.lineupMaskState && squad.lineupMaskState.playerPlacementById) delete squad.lineupMaskState.playerPlacementById[playerId];
  if (squad.lineupAssignments && squad.lineupAssignments[playerId]) delete squad.lineupAssignments[playerId];
}
function addPlayerToSquadReserve(world, club, player){
  var squad = world.squads[club.id] || (world.squads[club.id] = { playerIds:[], lineup:[], bench:[], reserve:[], tactics:Object.assign({}, LINEUP_TACTIC_DEFAULTS) });
  squad.playerIds = squad.playerIds || []; squad.lineup = squad.lineup || []; squad.bench = squad.bench || []; squad.reserve = squad.reserve || [];
  if (squad.playerIds.indexOf(player.id) < 0) squad.playerIds.push(player.id);
  if (squad.lineup.indexOf(player.id) < 0 && squad.bench.indexOf(player.id) < 0 && squad.reserve.indexOf(player.id) < 0) squad.reserve.push(player.id);
  assignShirtNumbersForClub(club, squad, world);
  return squad;
}
function playerSquadImportance(world, player, club){
  if (!world || !player || !club) return { rank:'reserve', factor:0 };
  var squad = (world.squads || {})[club.id] || { playerIds:[] };
  var overall = Number(calculatePlayerCurrentOverallAdvanced(player) || player.overall || 0);
  var peers = (squad.playerIds || []).map(function(id){ return world.players.byId[id]; }).filter(function(p){ return p && p.mainPosition === player.mainPosition; }).map(function(p){ return Number(calculatePlayerCurrentOverallAdvanced(p) || p.overall || 0); }).sort(function(a,b){ return b-a; });
  var index = peers.indexOf(overall);
  if (index <= 0 && overall >= Number(averageOverall(world, squad.playerIds || []) || overall) + 2) return { rank:'key', factor:.42 };
  if (index <= 0) return { rank:'starter', factor:.25 };
  if (index === 1) return { rank:'rotation', factor:.08 };
  return { rank:'reserve', factor:-.12 };
}
function transferPlayerInterestAssessment(world, player, targetClub, transferType){
  var sourceClub = player && player.clubId ? (((world||{}).clubs||{}).byId||{})[player.clubId] : null;
  if (!player || !targetClub || !sourceClub || sourceClub.id === targetClub.id) return { willing:false, score:0, reason:'Ein Wechsel ist in dieser Konstellation nicht möglich.' };
  var sourceAttraction = clubTransferAttractiveness(world, sourceClub);
  var targetAttraction = clubTransferAttractiveness(world, targetClub);
  var sourceSquad = (world.squads||{})[sourceClub.id] || { playerIds:[] };
  var targetSquad = (world.squads||{})[targetClub.id] || { playerIds:[] };
  var overall = Number(calculatePlayerCurrentOverallAdvanced(player) || player.overall || 50);
  var sourceAvg = Number(averageOverall(world, sourceSquad.playerIds || []) || overall);
  var targetAvg = Number(averageOverall(world, targetSquad.playerIds || []) || overall);
  var roleOpportunity = clampNumber((overall - targetAvg) * 2.1, -18, 18);
  var moraleEffect = (55 - playerMorale100(player)) * .18;
  var timing = squadPlanningTransferTimingPressure(world);
  var typeBonus = transferType === 'loan' ? ((Number(player.age || 25) <= 23 ? 12 : -3) + (overall < sourceAvg ? 10 : -4)) : 0;
  var score = 52 + (targetAttraction - sourceAttraction) * 9 + roleOpportunity + moraleEffect + typeBonus + timing * 5;
  score = clampNumber(Math.round(score),0,100);
  var willing = score >= 42;
  var reason = willing ? (transferType === 'loan' ? 'Der Spieler kann sich eine befristete Leihe grundsätzlich vorstellen.' : 'Der Spieler kann sich einen festen Wechsel grundsätzlich vorstellen.') : 'Der Spieler schätzt den sportlichen Schritt zu unserem Verein derzeit nicht attraktiv genug ein.';
  return { willing:willing, score:score, reason:reason, sourceAttraction:sourceAttraction, targetAttraction:targetAttraction };
}
function sellingClubNegotiationOpenness(world, player, targetClub, transferType){
  var sourceClub = player && player.clubId ? ((((world||{}).clubs||{}).byId)||{})[player.clubId] : null;
  if (!sourceClub || !targetClub) return { willing:false, reason:'Es gibt keinen abgebenden Verein.' };
  var containers = ensureWorldTransferPlanningContainers(world);
  var listing = containers.listings.byPlayerId[player.id] || null;
  if (listing) return { willing:true, reason:'Der Spieler ist gelistet; der Verein hört sich Angebote an.' };
  var importance = playerSquadImportance(world, player, sourceClub);
  var season = Number((world.meta||{}).seasonNumber || 1);
  var remaining = Math.max(0, Number(playerContractUntilSeason(player) || season) - season);
  var timing = squadPlanningTransferTimingPressure(world);
  var sameLeague = sourceClub.leagueKey && sourceClub.leagueKey === targetClub.leagueKey;
  if (transferType === 'loan') {
    if ((importance.rank === 'key' || importance.rank === 'starter') && Number(player.age || 25) > 23) return { willing:false, reason:'Der abgebende Verein lehnt eine Leihe ab, weil der Spieler fest für die aktuelle Mannschaft eingeplant ist.' };
    return { willing:true, reason:'Der Verein ist bereit, über eine Leihe zu sprechen.' };
  }
  if (importance.rank === 'key' && remaining >= 3 && timing > .55) return { willing:false, reason:'Der abgebende Verein möchte seinen Schlüsselspieler mit langfristigem Vertrag derzeit nicht abgeben.' };
  if (importance.rank === 'key' && sameLeague) return { willing:false, reason:'Der abgebende Verein möchte den Schlüsselspieler nicht an einen direkten Ligakonkurrenten abgeben.' };
  return { willing:true, reason:'Der Verein hört sich ein konkretes Ablöseangebot an.' };
}
function sellingClubTransferAssessment(world, player, targetClub, transferType, offer){
  var sourceClub = player && player.clubId ? (((world||{}).clubs||{}).byId||{})[player.clubId] : null;
  if (!sourceClub || !targetClub) return { score:0, label:'nicht möglich', reasons:['Kein abgebender Verein vorhanden.'], demand:0, boardScore:0, boardLabel:'nicht möglich' };
  offer = offer || {};
  var containers = ensureWorldTransferPlanningContainers(world);
  var listing = containers.listings.byPlayerId[player.id] || null;
  var market = Math.max(.01, Number(player.marketValue || 0));
  var season = Number((world.meta||{}).seasonNumber || 1);
  var remaining = Math.max(0, Number(playerContractUntilSeason(player) || season) - season);
  var importance = playerSquadImportance(world, player, sourceClub);
  var sameLeague = sourceClub.leagueKey && sourceClub.leagueKey === targetClub.leagueKey;
  var timing = squadPlanningTransferTimingPressure(world);
  var demand = listing && Number(listing.askingPrice || 0) > 0 ? Number(listing.askingPrice) : market * (1 + remaining * .13 + importance.factor + (sameLeague ? .15 : 0));
  if (!listing && importance.rank === 'key' && timing > .72) demand *= 1.18;
  demand = contractRoundMoney(Math.max(.01,demand),.01);
  var reasons = [];
  if (listing) reasons.push('Der Spieler ist transfergelistet; die hinterlegte Preisvorstellung ist der wichtigste Anker.');
  if (importance.rank === 'key') reasons.push('Der Spieler ist sportlich besonders wichtig.');
  else if (importance.rank === 'reserve') reasons.push('Der Spieler ist im aktuellen Kader ersetzbar.');
  if (remaining >= 3) reasons.push('Die lange Vertragslaufzeit stärkt die Position des abgebenden Vereins.');
  if (sameLeague) reasons.push('Ein Wechsel zu einem direkten Ligakonkurrenten wird kritischer bewertet.');
  if (timing > .75 && importance.rank !== 'reserve') reasons.push('Spät im Transferfenster ist Ersatz schwer zu beschaffen.');
  var cash = Math.max(.01, financeCurrentCash(world,targetClub));
  if (transferType === 'loan') {
    var wageShare=Number(offer.wageSharePercent||0),loanFee=Number(offer.loanFee||0),minimumShare=Number(offer.minimumAppearanceShare||0),penalty=Number(offer.nonAppearancePenalty||0),purchaseOption=Number(offer.purchaseOptionFee||0);
    var sourceNeed=importance.rank==='key'?24:importance.rank==='starter'?14:0,development=Number(player.age||25)<=23?14:0;
    var optionBonus=offer.purchaseObligation&&offer.purchaseObligation!=='none'?8:(purchaseOption>=market*.8?5:0);
    var recallBonus=offer.recallOption==='winter'?4:0;
    var scoreLoan=45+wageShare*.32+Math.min(18,loanFee/Math.max(.01,market)*20)+development+minimumShare*.12+Math.min(7,penalty/Math.max(.01,market)*15)+optionBonus+recallBonus-sourceNeed;
    var boardLoanCost=loanFee+Math.max(0,Number(player.salaryExpectation||0))*(wageShare/100);
    var boardScoreLoan=clampNumber(Math.round(82-boardLoanCost/cash*30-(minimumShare>=75?6:0)-(penalty>0?3:0)+(purchaseOption>0?2:0)),0,100);
    if(minimumShare>=50)reasons.push('Die zugesagte Einsatzzeit unterstützt die Entwicklung des Spielers.');
    if(offer.purchaseObligation&&offer.purchaseObligation!=='none')reasons.push('Eine mögliche Kaufpflicht erhöht den langfristigen Wert des Angebots.');
    return { score:clampNumber(Math.round(scoreLoan),0,100), label:scoreLoan >= 72 ? 'Leihe gut vorstellbar' : scoreLoan >= 50 ? 'verhandlungsbereit' : 'eher ablehnend', reasons:reasons, demand:demand, boardScore:boardScoreLoan, boardLabel:boardScoreLoan >= 60 ? 'vertretbar' : 'kritisch' };
  }
  var fee=Number(offer.fee||0),appearanceBonus=Number(offer.appearanceBonusFee||0),promotionBonus=Number(offer.promotionBonusFee||0),sellOn=Number(offer.sellOnPercent||0),buyBackFee=Number(offer.buyBackFee||0);
  var sellerPackage=fee+appearanceBonus*.65+promotionBonus*.45+market*(sellOn/100)*.22+(offer.firstRefusal==='yes'?market*.025:0)+(buyBackFee>fee?Math.min(market*.06,(buyBackFee-fee)*.08):0);
  var paymentPenalty=offer.paymentModel==='three_installments'?.08:offer.paymentModel==='two_installments'?.04:0;
  var ratio=sellerPackage/Math.max(.01,demand)*(1-paymentPenalty);
  var score=clampNumber(Math.round(25+ratio*68+(listing?7:0)),0,100);
  var expectedCost=fee+appearanceBonus*.45+promotionBonus*.25;
  var boardScore=clampNumber(Math.round(88-expectedCost/cash*40-(sellOn>=20?5:sellOn>=10?2:0)-(buyBackFee>0?3:0)+(offer.paymentModel==='three_installments'?5:offer.paymentModel==='two_installments'?3:0)),0,100);
  if(sellOn>0)reasons.push('Die Weiterverkaufsbeteiligung verbessert den möglichen späteren Ertrag.');
  if(appearanceBonus>0||promotionBonus>0)reasons.push('Erfolgsabhängige Boni erhöhen den Gesamtwert des Pakets.');
  if(paymentPenalty>0)reasons.push('Die Ratenzahlung mindert den unmittelbaren Wert für den abgebenden Verein.');
  return { score:score, label:score >= 84 ? 'würde annehmen' : score >= 55 ? 'verhandlungsbereit' : 'zu niedrig', reasons:reasons, demand:demand, boardScore:boardScore, boardLabel:boardScore >= 72 ? 'vertretbar' : boardScore >= 45 ? 'kritisch' : 'nicht tragbar' };
}
