function clubTransferOfferNeedsImprovement(assessment){return assessment&&Number(assessment.score||0)>=35&&Number(assessment.score||0)<72&&Number(assessment.boardScore||0)>=25;}
function decideClubTransferResponse(world,player,targetClub,type,offer,assessment,options){
  options=options||{};
  if(Number(assessment.boardScore||0)<25)return{type:'board_veto',title:'Vorstand warnt',message:'Unser Vorstand hält die Konditionen für wirtschaftlich nicht tragbar.'};
  if(!options.forceFinal&&clubTransferOfferNeedsImprovement(assessment))return{type:'needs_adjustment',title:'Nachbesserung möglich',message:'Der abgebende Verein ist noch nicht überzeugt. Entscheidend sind Ablöse, sportliche Bedeutung und Ersatzlage.'};
  var seed=deterministicHash([player.id,targetClub.id,type,JSON.stringify(offer),((world.calendar||{}).currentSlotKey||''),options.insist?'insist':'normal','kf0205'].join('|'));
  var score=Number(assessment.score||0);
  if(options.insist)return score>=58&&seed%4!==0?{type:'accepted',accepted:true,title:'Angebot angenommen',message:'Der abgebende Verein akzeptiert die unveränderten Konditionen.'}:{type:'rejected',accepted:false,title:'Angebot abgelehnt',message:'Der abgebende Verein lehnt die unveränderten Konditionen endgültig ab.'};
  if(score>=84)return{type:'accepted',accepted:true,title:'Verein stimmt zu',message:'Der abgebende Verein akzeptiert die Konditionen.'};
  if(score>=62){if(seed%3===0)return{type:'pending',delaySlots:1+seed%3,title:'Bedenkzeit',message:'Der abgebende Verein prüft die Kaderlage und mögliche Konkurrenzangebote.'};return{type:'accepted',accepted:true,title:'Verein stimmt zu',message:'Der abgebende Verein akzeptiert die Konditionen.'};}
  if(score>=42&&seed%2===0)return{type:'pending',delaySlots:2,title:'Bedenkzeit',message:'Der abgebende Verein möchte die Marktlage noch beobachten.'};
  return{type:'rejected',accepted:false,title:'Angebot abgelehnt',message:'Der abgebende Verein lehnt die Konditionen ab.'};
}
