    return '<tr class="data-row"><td><button class="squad-name-btn" type="button" data-action="open-player-profile" data-player-id="' + escapeHtml(row.player.id) + '">' + escapeHtml(row.player.fullName || '-') + '</button></td><td>' + escapeHtml(row.art) + '</td><td>' + escapeHtml(row.from) + '</td><td>' + escapeHtml(row.to) + '</td><td class="align-right">' + escapeHtml(row.offer) + '</td><td class="align-right">' + escapeHtml(row.demand) + '</td><td><span class="contract-status-text-' + escapeHtml(row.statusClass) + '">' + escapeHtml(row.statusLabel) + '</span></td><td><div class="contract-action-cell squad-planning-activity-actions">' + squadPlanningActivityActionsHtml(row) + '</div></td></tr>';
