  return '<div class="finance-modal-block"><p>'+escapeHtml(player.fullName||'-')+(listed?' befindet sich auf der Scoutingliste.':' befindet sich noch nicht auf der Scoutingliste.')+'</p><div class="modal-actions sponsor-modal-actions">'+(listed?'<button class="ghost-btn is-danger" type="button" data-action="player-profile-scout-remove" data-player-id="'+escapeHtml(player.id)+'">Von Scoutingliste entfernen</button>':'<button class="primary-btn" type="button" data-action="player-profile-scout-add" data-player-id="'+escapeHtml(player.id)+'">Auf Scoutingliste setzen</button>')+'</div></div>';
