/* KF_0.21.1 finance planning, squad-value licensing and player-facing cleanup. */
function kf0211Rules(){
  var rules=((window.KFStaticData||{}).financeLicenceRules)||{};
  return { clean:Number(rules.cleanDeficitPercent||5), denied:Number(rules.deniedDeficitPercent||15) };
}
function kf0211ScheduledDeparture(world,playerId,clubId){
  var box=((((world||{}).transferMarket||{}).futureMoves)||{}), order=box.order||[], byId=box.byId||{};
  for(var i=0;i<order.length;i++){
    var m=byId[order[i]];
    if(!m||m.status!=='scheduled'||m.playerId!==playerId)continue;
    if(m.fromClubId===clubId && (m.type==='permanent'||m.type==='precontract'||m.type==='loan_option'||m.type==='loan_obligation'||m.type==='free_agent'))return true;
  }
  return false;
}
function kf0211LicenceSquadMarketValue(world,clubId){
  var season=Number((((world||{}).meta)||{}).seasonNumber||1), total=0, count=0;
  (((world||{}).players||{}).order||[]).forEach(function(pid){
    var p=world.players.byId[pid];if(!p||p.retired)return;
    var owned=p.loan ? p.loan.parentClubId===clubId : p.clubId===clubId;
    if(!owned)return;
    if(kf0211ScheduledDeparture(world,p.id,clubId))return;
    var contractEnd=Number((p.contract&&p.contract.validUntilSeason) || 0);
    if(contractEnd>0 && contractEnd<=season)return;
    total+=Math.max(0,Number(p.marketValue||0));count++;
  });
  return { value:round2(total), playerCount:count };
}
function kf0211ApplyLicenceMetrics(world,club,snap){
  var asset=kf0211LicenceSquadMarketValue(world,club.id), deficit=Math.max(0,-Number(snap.nextResult||0)), rules=kf0211Rules();
  var pct=asset.value>0 ? round2(deficit/asset.value*100) : (deficit>0?999:0);
  var status=pct<=rules.clean?'Lizenz ohne Auflagen':pct<=rules.denied?'Lizenz mit Sanierungsauflagen':'Lizenz verweigert';
  snap.licenceSquadMarketValue=asset.value;snap.licenceSquadPlayerCount=asset.playerCount;snap.licenceDeficit=round2(deficit);snap.licenceDeficitPercent=pct;snap.licenceStatus=status;snap.licenceSaldo=round2(Number(snap.nextResult||0));snap.licenceBuffer=0;snap.licencePlanningResult=round2(Number(snap.nextResult||0));
  snap.licenceBasisNote='Lizenzgrundlage ist die Saisonplanung. Defizit bis '+String(rules.clean)+' % des verwertbaren eigenen Kadermarktwerts: ohne Auflagen; bis '+String(rules.denied)+' %: Sanierungsauflagen; darüber: Lizenz verweigert.';
  return snap;
}
var kf0211BaseBuildFinanceSnapshot=buildFinanceSnapshot;
buildFinanceSnapshot=function(world,club,scenario){return kf0211ApplyLicenceMetrics(world,club,kf0211BaseBuildFinanceSnapshot(world,club,scenario||'current'));};

