/* KF_0.21.1 help preferences are UI state only; never simulation truth. */
var KF0211_HELP_STORAGE_KEY='kf0211_ui_help';
var KF0211_HELP_FALLBACK={asked:false,enabled:true,seen:{}};
function kf0211ReadHelpPrefs(){
  var value=null;
  try{if(typeof window.localStorage!=='undefined')value=window.localStorage.getItem(KF0211_HELP_STORAGE_KEY);}catch(e){}
  if(value){try{var parsed=JSON.parse(value);return {asked:!!parsed.asked,enabled:parsed.enabled!==false,seen:parsed.seen&&typeof parsed.seen==='object'?parsed.seen:{}};}catch(e){}}
  return {asked:!!KF0211_HELP_FALLBACK.asked,enabled:KF0211_HELP_FALLBACK.enabled!==false,seen:Object.assign({},KF0211_HELP_FALLBACK.seen||{})};
}
function kf0211WriteHelpPrefs(prefs){
  var clean={asked:!!prefs.asked,enabled:prefs.enabled!==false,seen:Object.assign({},prefs.seen||{})};KF0211_HELP_FALLBACK=clean;
  try{if(typeof window.localStorage!=='undefined')window.localStorage.setItem(KF0211_HELP_STORAGE_KEY,JSON.stringify(clean));}catch(e){}
  return clean;
}
function kf0211HelpText(view){return (((window.KFStaticData||{}).uiHelp||{}).menus||{})[view]||'';}
function kf0211OpenHelpChoice(){
  openModal({title:'Kurze Spielhilfen',bodyHtml:'<div class="finance-modal-block"><p>Möchtest du beim ersten Öffnen wichtiger Bereiche eine kurze Erklärung erhalten?</p><p>Tooltips an Begriffen und Werten bleiben unabhängig davon verfügbar. Die Spielhilfen verändern keine Simulation und können unter ⚙ Optionen jederzeit geändert werden.</p><div class="modal-actions sponsor-modal-actions"><button class="primary-btn" type="button" data-action="ui-help-enable">Spielhilfen aktivieren</button><button class="ghost-btn" type="button" data-action="ui-help-disable">Ohne Tutorials spielen</button></div></div>',size:'medium',popupType:'interaction',lockBackdrop:true});renderModal();
}
function kf0211MaybeShowTutorial(view){
  if(!((AppState.session||{}).activeClubId))return false;var prefs=kf0211ReadHelpPrefs();
  if(!prefs.asked){kf0211OpenHelpChoice();return true;}
  if(!prefs.enabled||prefs.seen[view])return false;var text=kf0211HelpText(view);if(!text)return false;
  prefs.seen[view]=true;kf0211WriteHelpPrefs(prefs);openModal({title:'Kurzhilfe: '+String(view==='office'?'Büro':view==='squad'?'Kader':view==='lineup'?'Aufstellung':view==='calendar'?'Kalender':view==='statistics'?'Statistik':view==='finance'?'Finanzen':view==='contracts'?'Verträge':view==='squad-planning'?'Kaderplanung':'Spielbereich'),body:text,size:'medium',popupType:'interaction'});renderModal();return true;
}
