  if(action==='ui-help-enable'){var p=kf0211ReadHelpPrefs();p.asked=true;p.enabled=true;kf0211WriteHelpPrefs(p);closeModal();renderModal();kf0211MaybeShowTutorial((AppState.ui||{}).currentView||'office');return;}
  if(action==='ui-help-disable'){var p2=kf0211ReadHelpPrefs();p2.asked=true;p2.enabled=false;kf0211WriteHelpPrefs(p2);closeModal();renderModal();return;}
  if(action==='ui-help-toggle'){var p3=kf0211ReadHelpPrefs();p3.asked=true;p3.enabled=!p3.enabled;kf0211WriteHelpPrefs(p3);closeModal();renderModal();kf0211OptionsModal();return;}
  if(action==='ui-help-reset'){var p4=kf0211ReadHelpPrefs();p4.asked=true;p4.enabled=true;p4.seen={};kf0211WriteHelpPrefs(p4);closeModal();renderModal();kf0211OptionsModal();return;}
  return kf0211BaseHandleAction(action,actionEl);
