  var pct = Number((snap || {}).licenceDeficitPercent || 0), count = Number((snap || {}).futureSquadPlayerCount || 0), strength = Number((snap || {}).futureSquadStrength || 0);
  return '<td class="finance-0212-licence ' + cls + '"><div class="finance-0212-licence-box finance-0214-licence-box"><strong>' + escapeHtml(status) + '</strong><span>Defizit ' + escapeHtml(pct.toFixed(2)) + ' %</span><em>' + escapeHtml(label) + ' · Kader ' + String(count) + ' · Staerke ' + String(strength) + '</em><em>verwertbarer Kader ' + escapeHtml(financeEuroM(Number((snap || {}).licenceSquadMarketValue || 0))) + '</em></div></td>';
