  var season=Number((world.meta||{}).seasonNumber||1),slot=((world.calendar||{}).currentSlotKey||'bonus');
  var payer=addFinanceEvent(world,payerClubId,{id:financeEventId(payerClubId,'clausePay_'+player.id+'_'+key,season,slot),type:'transferExpense',amount:-amount,seasonId:season,slotKey:slot,label:label,source:'transferClause',playerId:player.id,eventKey:key});
  var beneficiary=addFinanceEvent(world,beneficiaryClubId,{id:financeEventId(beneficiaryClubId,'clauseIncome_'+player.id+'_'+key,season,slot),type:'transferIncome',amount:amount,seasonId:season,slotKey:slot,label:label,source:'transferClause',playerId:player.id,eventKey:key});
  var paid=!!(payer||beneficiary);
