  var ids=Object.keys(world.players.byId).filter(function(id){var p=world.players.byId[id];return !!(p&&p.retired);}),migrated=0;
  ids.forEach(function(id){var p=world.players.byId[id];if(!p)return;kf0262ArchiveAndRemoveRetiredPlayer(world,p,p.retiredSeason);migrated+=1;});
