  if(!world)return {season:1,matchesDelta:[],financeEventsDelta:[],matchIds:[],financeKeys:[]};
  var season=kf029EnsureDetailSeason(),matchesDelta=[],matchIds=[],financeEventsDelta=[],financeKeys=[];
